"use client";

import * as React from "react";

import type { ViewerResource } from "@/lib/viewer-resource";

import { MarkdownGreenfieldContent } from "./markdown-greenfield-content";
import { PlainTextViewerFrame } from "./plain-text-viewer-frame";
import { ChenglouTextViewerContent } from "./text-viewer-chenglou-content";
import { TextViewerFallback } from "./text-viewer-chrome";
import { resolveTextViewerMode } from "./text-viewer-layout";
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types";

export type {
  TextDocumentSource,
  TextLineRange,
  TextViewerHandle,
  TextViewerProps,
} from "./text-viewer-types";

export type TextResourceContentProps = Omit<TextViewerProps, "source"> & {
  resource: ViewerResource;
};

type RoutedTextViewerContentProps = Omit<TextViewerProps, "source"> & {
  source?: TextViewerProps["source"];
  resource: ViewerResource;
  retryVersion: number;
  forwardedRef?: React.ForwardedRef<TextViewerHandle>;
};

export type TextViewerProviderProps = {
  children: React.ReactNode;
  resource: ViewerResource;
};

export type TextViewerDocumentProps = Omit<
  TextResourceContentProps,
  "resource"
>;

export const TextViewer = React.forwardRef<TextViewerHandle, TextViewerProps>(
  function TextViewer(props, ref) {
    return (
      <PlainTextViewerFrame
        props={props}
        forwardedRef={ref}
        clientFallbackPolicy="always"
        Fallback={TextViewerFallback}
        Content={TextViewerRoutedContent}
      />
    );
  },
);

const TextViewerResourceContext = React.createContext<ViewerResource | null>(
  null,
);

export function TextViewerProvider({
  children,
  resource,
}: TextViewerProviderProps) {
  return (
    <TextViewerResourceContext.Provider value={resource}>
      {children}
    </TextViewerResourceContext.Provider>
  );
}

function useTextViewerResource(): ViewerResource {
  const resource = React.useContext(TextViewerResourceContext);
  if (!resource) {
    throw new Error(
      "TextViewerDocument must be used within TextViewerProvider.",
    );
  }
  return resource;
}

export const TextViewerDocument = React.forwardRef<
  TextViewerHandle,
  TextViewerDocumentProps
>(function TextViewerDocument(props, ref) {
  const resource = useTextViewerResource();
  return <TextResourceContent {...props} ref={ref} resource={resource} />;
});

export const TextResourceContent = React.forwardRef<
  TextViewerHandle,
  TextResourceContentProps
>(function TextResourceContent({ resource, ...props }, ref) {
  return (
    <PlainTextViewerFrame
      props={props}
      resource={resource}
      forwardedRef={ref}
      clientFallbackPolicy="always"
      Fallback={TextViewerFallback}
      Content={TextViewerRoutedContent}
    />
  );
});

function TextViewerRoutedContent(props: RoutedTextViewerContentProps) {
  const mode =
    props.mode ??
    resolveTextViewerMode({
      fileName: props.resource.fileName,
      mimeType: props.resource.content.mimeType,
    });
  const source =
    props.source ??
    (props.resource.descriptor.source as TextViewerProps["source"]);

  if (mode === "markdown") {
    return <MarkdownGreenfieldContent {...props} source={source} />;
  }

  return <ChenglouTextViewerContent {...props} mode="text" source={source} />;
}

"use client";

import * as React from "react";

import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource";
import { useIsClient } from "@/components/ui/use-is-client";

import {
  descriptorResetKey,
  type FileDescriptor,
  type FileViewerFallbackSize,
  type FileViewerProps as FileViewerCoreProps,
  type FileViewerDocumentChrome,
} from "./file-viewer-core";
import {
  ViewerControlsRegistrationProvider,
  type ViewerControlsState,
} from "./viewer-controls";

type FileViewerProviderProps = Pick<
  FileViewerCoreProps,
  "as" | "fallbackFrameSize" | "fallbackSlideSize" | "isolateStyles" | "source"
> & {
  children: React.ReactNode;
  documentChrome?: FileViewerDocumentChrome;
};

type FileViewerContextValue = {
  descriptor: FileDescriptor;
  descriptorKey: string;
  descriptorSignal: AbortSignal;
  documentChrome: FileViewerDocumentChrome;
  fallbackFrameSize?: FileViewerFallbackSize;
  fallbackSlideSize?: FileViewerFallbackSize;
  isClient: boolean;
  isolateStyles: boolean;
  resource: ViewerResource;
};

type FileViewerControlsContextValue = {
  controlsState: ViewerControlsState | null;
};

const FileViewerContext = React.createContext<FileViewerContextValue | null>(
  null,
);
const FileViewerControlsContext =
  React.createContext<FileViewerControlsContextValue | null>(null);

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

// Per-descriptor cancellation signal. Aborting is deferred a macrotask so a
// keyed remount (or StrictMode's mount/unmount/mount) can cancel the pending
// abort and keep reusing the shared resource request instead of tearing it down
// and immediately refetching. Powers HtmlFileContent's external-cancellation
// contract (see html-viewer-edge-cases: abort mid-load).
function useDescriptorSignal(descriptorKey: string): AbortSignal {
  const controller = React.useMemo(() => {
    void descriptorKey;
    return new AbortController();
  }, [descriptorKey]);
  const abortTimerRef = React.useRef<{
    controller: AbortController;
    timer: ReturnType<typeof setTimeout>;
  } | null>(null);

  useIsomorphicLayoutEffect(() => {
    if (abortTimerRef.current?.controller === controller) {
      clearTimeout(abortTimerRef.current.timer);
      abortTimerRef.current = null;
    }

    return () => {
      const abortTimer = {
        controller,
        timer: setTimeout(() => {
          controller.abort();
          if (abortTimerRef.current === abortTimer) {
            abortTimerRef.current = null;
          }
        }, 0),
      };
      abortTimerRef.current = abortTimer;
    };
  }, [controller]);

  return controller.signal;
}

export function useFileViewerContext() {
  const context = React.useContext(FileViewerContext);
  if (!context) {
    throw new Error("File viewer parts must be used within FileViewer.");
  }
  return context;
}

export function useFileViewerControlsState(): ViewerControlsState | null {
  const context = React.useContext(FileViewerControlsContext);
  if (!context) {
    throw new Error("File viewer controls must be used within FileViewer.");
  }
  return context.controlsState;
}

export function useOptionalFileViewerResource(): ViewerResource | null {
  return React.useContext(FileViewerContext)?.resource ?? null;
}

export function useFileViewerResource(): ViewerResource {
  const resource = useOptionalFileViewerResource();
  if (!resource) {
    throw new Error("useFileViewerResource must be used within FileViewer.");
  }
  return resource;
}

export function FileViewerProvider({
  as,
  children,
  documentChrome = "shell",
  fallbackFrameSize,
  fallbackSlideSize,
  isolateStyles = false,
  source,
}: FileViewerProviderProps) {
  const isClient = useIsClient();
  const resource = React.useMemo(
    () => createViewerResource(source, as),
    [source, as],
  );
  // createViewerResource already resolved this descriptor; reuse it instead of
  // recomputing. The interned resource is referentially stable across renders,
  // so the context value below stays stable too (a fresh resolve would mint a
  // new object every render and defeat the useMemo).
  const descriptor = resource.descriptor;
  const descriptorKey = descriptorResetKey(descriptor);
  const descriptorSignal = useDescriptorSignal(descriptorKey);
  const [controlsRegistration, setControlsRegistration] = React.useState<{
    descriptorKey: string;
    state: ViewerControlsState | null;
  }>({ descriptorKey, state: null });
  const controlsState =
    controlsRegistration.descriptorKey === descriptorKey
      ? controlsRegistration.state
      : null;
  const handleControlsChange = React.useCallback(
    (state: ViewerControlsState | null) => {
      setControlsRegistration({ descriptorKey, state });
    },
    [descriptorKey],
  );
  const value = React.useMemo<FileViewerContextValue>(
    () => ({
      descriptor,
      descriptorKey,
      descriptorSignal,
      documentChrome,
      fallbackFrameSize,
      fallbackSlideSize,
      isClient,
      isolateStyles,
      resource,
    }),
    [
      descriptor,
      descriptorKey,
      descriptorSignal,
      documentChrome,
      fallbackFrameSize,
      fallbackSlideSize,
      isClient,
      isolateStyles,
      resource,
    ],
  );
  const controlsValue = React.useMemo<FileViewerControlsContextValue>(
    () => ({
      controlsState,
    }),
    [controlsState],
  );

  return (
    <FileViewerContext.Provider value={value}>
      <FileViewerControlsContext.Provider value={controlsValue}>
        <ViewerControlsRegistrationProvider
          onControlsChange={handleControlsChange}
        >
          {children}
        </ViewerControlsRegistrationProvider>
      </FileViewerControlsContext.Provider>
    </FileViewerContext.Provider>
  );
}

import {
  detectCategory,
  extensionOf,
  extractName,
  resolveViewerDescriptor,
  textPayloadKey,
  type FileCategory,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source";

export type { FileCategory, ViewerSource };
export type FileViewerDocumentChrome = "shell" | "standalone";
export type FileViewerFallbackSize = { width: number; height: number };

export interface FileViewerProps {
  source: ViewerSource;
  as?: FileCategory;
  className?: string;
  /** Intrinsic first-frame size for image/TIFF loading skeletons. */
  fallbackFrameSize?: FileViewerFallbackSize;
  /** Intrinsic first-slide size for PPTX loading skeletons. */
  fallbackSlideSize?: FileViewerFallbackSize;
  isolateStyles?: boolean;
}

export type FileDescriptor = ViewerDescriptor;

export function resolveFileDescriptor({
  source,
  as,
}: FileViewerProps): FileDescriptor {
  return resolveViewerDescriptor({
    source,
    category: as,
  });
}

export function descriptorResetKey(descriptor: FileDescriptor): string {
  return [
    descriptorIdentityResetKey(descriptor),
    descriptor.displayName,
    descriptor.mimeType ?? "",
    descriptor.category,
  ].join("\u0000");
}

function descriptorIdentityResetKey(descriptor: FileDescriptor): string {
  if (
    descriptor.source.kind === "text" &&
    descriptor.source.identityKey == null
  ) {
    return textPayloadKey(descriptor.source.text);
  }
  return descriptor.identityKey;
}

export function isProseTextDescriptor(descriptor: FileDescriptor): boolean {
  if (descriptor.category !== "text") return false;

  const extension = extensionOf(descriptor.fileName);
  if (extension === "txt" || extension === "text") return true;
  return !extension && descriptor.mimeType?.toLowerCase() === "text/plain";
}

export { detectCategory, extensionOf, extractName };

export async function timed<T>(
  label: string,
  fn: () => Promise<T>,
): Promise<T> {
  const on =
    typeof globalThis !== "undefined" &&
    (globalThis as { __FILE_VIEWER_PROFILE__?: boolean })
      .__FILE_VIEWER_PROFILE__;
  if (!on) return fn();
  const t0 = performance.now();
  try {
    return await fn();
  } finally {
    console.log(
      `[file-viewer] ${label} ${(performance.now() - t0).toFixed(1)}ms`,
    );
  }
}

"use client";

/* eslint-disable no-restricted-syntax -- TODO(no-useEffect): existing direct React effect usage; migrate to useMountEffect or a Rule 1-5 replacement. */

import * as React from "react";
import { AlertCircle, Check, Copy } from "lucide-react";

import { type ViewerDownloadAction } from "@/lib/viewer-download-actions";

import { Skeleton } from "./skeleton";
import { TextCodeViewerFrame } from "./text-code-viewer-chrome";
import type { ViewerDownloadErrorHandler } from "./viewer-download";
import {
  ViewerControls,
  ViewerControlButton,
  ViewerControlsSkeleton,
} from "./viewer-controls";

export type ViewerClipboardCopyStatus = "copied" | "failed" | "idle";

export function TextViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string;
  bare?: boolean;
  children: React.ReactNode;
}) {
  return (
    <TextCodeViewerFrame
      bare={bare}
      bareClassName="h-full bg-background"
      className={className}
      dataSlot="text-viewer"
      framedClassName="rounded-xl border bg-background"
    >
      {children}
    </TextCodeViewerFrame>
  );
}

export function TextViewerFallback({
  className,
  controls = true,
  download = true,
  bare,
}: {
  className?: string;
  controls?: boolean;
  download?: boolean;
  bare?: boolean;
}) {
  return (
    <TextViewerFrame className={className} bare={bare}>
      {controls ? (
        <ViewerControlsSkeleton title zoom download={download} />
      ) : null}
      <div
        className="min-h-0 flex-1 space-y-3 overflow-hidden p-5"
        data-slot="text-body-skeleton"
      >
        {Array.from({ length: 10 }, (_, index) => (
          <Skeleton
            key={index}
            className="h-4"
            style={{ width: `${48 + ((index * 17) % 44)}%` }}
          />
        ))}
      </div>
    </TextViewerFrame>
  );
}

export function TextViewerControls({
  wordCount,
  fontScale,
  copyText,
  copyLabel = "Copy text",
  downloadAction,
  extra,
  leading,
  onDownloadError,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  wordCount: number;
  fontScale: number;
  copyText?: string;
  copyLabel?: string;
  downloadAction?: ViewerDownloadAction | null;
  extra?: React.ReactNode;
  leading?: React.ReactNode;
  onDownloadError?: ViewerDownloadErrorHandler;
  onZoomOut: () => void;
  onZoomIn: () => void;
  onResetZoom: () => void;
}) {
  const copyControl =
    copyText == null ? null : (
      <TextViewerCopyControl label={copyLabel} text={copyText} />
    );

  return (
    <ViewerControls
      title={leading ?? `${wordCount} word${wordCount === 1 ? "" : "s"}`}
      zoom={{
        scale: fontScale,
        onZoomOut,
        onZoomIn,
        onFit: onResetZoom,
        fitLabel: "Reset zoom",
      }}
      downloads={downloadAction ? [downloadAction] : undefined}
      onDownloadError={onDownloadError}
      extra={
        extra == null && copyControl == null ? null : (
          <span className="flex min-w-0 items-center gap-1">
            {extra}
            {copyControl}
          </span>
        )
      }
    />
  );
}

function TextViewerCopyControl({
  label,
  text,
}: {
  label: string;
  text: string;
}) {
  const { copy, status } = useViewerClipboardCopy();

  const copyText = () => {
    copy(text);
  };

  const buttonLabel =
    status === "copied"
      ? "Copied"
      : status === "failed"
        ? "Copy failed"
        : label;

  return (
    <ViewerControlButton label={buttonLabel} onClick={copyText} type="button">
      {status === "copied" ? (
        <Check />
      ) : status === "failed" ? (
        <AlertCircle />
      ) : (
        <Copy />
      )}
    </ViewerControlButton>
  );
}

export function useViewerClipboardCopy({
  resetDelay = 1200,
}: {
  resetDelay?: number;
} = {}) {
  const [status, setStatus] = React.useState<ViewerClipboardCopyStatus>("idle");
  const timeoutRef = React.useRef<number | null>(null);
  const isMountedRef = React.useRef(true);
  const copyAttemptRef = React.useRef(0);

  React.useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      clearViewerClipboardCopyReset(timeoutRef);
    };
  }, []);

  const scheduleReset = React.useCallback(() => {
    clearViewerClipboardCopyReset(timeoutRef);
    timeoutRef.current = window.setTimeout(() => {
      timeoutRef.current = null;
      if (isMountedRef.current) setStatus("idle");
    }, resetDelay);
  }, [resetDelay]);

  const copy = React.useCallback(
    (text: string) => {
      clearViewerClipboardCopyReset(timeoutRef);
      const copyAttempt = copyAttemptRef.current + 1;
      copyAttemptRef.current = copyAttempt;
      const isCurrentAttempt = () =>
        isMountedRef.current && copyAttemptRef.current === copyAttempt;

      try {
        const clipboard = navigator.clipboard;
        const writeText = clipboard?.writeText;
        if (typeof writeText !== "function") {
          setStatus("failed");
          scheduleReset();
          return;
        }

        void Promise.resolve(writeText.call(clipboard, text)).then(
          () => {
            if (!isCurrentAttempt()) return;
            setStatus("copied");
            scheduleReset();
          },
          () => {
            if (!isCurrentAttempt()) return;
            setStatus("failed");
            scheduleReset();
          },
        );
      } catch {
        setStatus("failed");
        scheduleReset();
      }
    },
    [scheduleReset],
  );

  return { copy, status };
}

function clearViewerClipboardCopyReset(
  timeoutRef: React.MutableRefObject<number | null>,
) {
  if (timeoutRef.current === null) return;
  window.clearTimeout(timeoutRef.current);
  timeoutRef.current = null;
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

export function TextCodeViewerFrame({
  bare,
  bareClassName,
  children,
  className,
  dataSlot,
  framedClassName,
}: {
  bare?: boolean;
  bareClassName: string;
  children: React.ReactNode;
  className?: string;
  dataSlot: string;
  framedClassName: string;
