import type { ViewerDownloadErrorHandler } from "./viewer-download";

const DEFAULT_VIEWPORT_HEIGHT = 640;
const DEFAULT_VIEWPORT_WIDTH = 900;
const INITIAL_CONTENT_WIDTH = 820;
const VIEWER_HORIZONTAL_PADDING = 32;
const OVERSCAN_PX = 800;
const MARKDOWN_GREENFIELD_HIGHLIGHT_STYLE = {
  backgroundColor:
    "color-mix(in oklab, var(--foreground) 8%, var(--background))",
  boxShadow: "inset 2px 0 0 0 var(--primary)",
} satisfies React.CSSProperties;

type MarkdownIdleWindow = Window &
  typeof globalThis & {
    cancelIdleCallback?: Window["cancelIdleCallback"];
    requestIdleCallback?: Window["requestIdleCallback"];
  };

type ViewportSize = {
  height: number;
  width: number;
};

type MarkdownScrollToLineOptions = ScrollToOptions & {
  preferredChunkId?: string | null;
};

export type MarkdownViewerProps = TextViewerProps & {
  /** Bind document fragment IDs to window.location.hash. Disable for embedded previews. */
  urlFragmentNavigation?: boolean;
};

export function MarkdownGreenfieldContent({
  resource,
  className,
  controls = true,
  download = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
  urlFragmentNavigation = true,
}: MarkdownViewerProps & {
  resource: ViewerResource;
  retryVersion: number;
  forwardedRef?: React.ForwardedRef<TextViewerHandle>;
}) {
  const bounds = React.useMemo(
    () => resolvedTextViewerBounds({ maxBytes, maxLines }),
    [maxBytes, maxLines],
  );
  const text = React.useMemo(
    () =>
      readTextResource({
        bounds,
        content: resource.content,
        retryVersion,
      }),
    [bounds, resource.content, retryVersion],
  );
  const parsedDocument = useMarkdownGreenfieldDocument(text);
  const pendingDocument = React.useMemo(
    () => createMarkdownGreenfieldDocument(" "),
    [],
  );
  const document = parsedDocument ?? pendingDocument;
  const isDocumentPending = parsedDocument == null;
  const documentMeasurementId = React.useMemo(
    () => measurementDocumentIdForText(text),
    [text],
  );
  const downloadAction = download ? resource.originalDownload : null;
  const [downloadError, setDownloadError] = React.useState("");
  const [fontScale, setFontScale] = React.useState(1);
  const [measuredHeights, setMeasuredHeights] = React.useState(
    () => new Map<string, number>(),
  );
  const [measuredHeightsRevision, setMeasuredHeightsRevision] =
    React.useState(0);
  const [scrollTop, setScrollTop] = React.useState(0);
  const [viewportSize, setViewportSize] = React.useState<ViewportSize>({
    height: 0,
    width: 0,
  });
  const [contentWidth, setContentWidth] = React.useState(INITIAL_CONTENT_WIDTH);
  const viewportRef = React.useRef<HTMLDivElement | null>(null);
  const scrollTopRef = React.useRef(0);
  const scrollFrameRef = React.useRef<number | null>(null);
  const pendingMeasuredHeightsRef = React.useRef(new Map<string, number>());
  const measuredHeightFrameRef = React.useRef<number | null>(null);
  const pendingAnchorRef = React.useRef<MarkdownGreenfieldScrollAnchor | null>(
    null,
  );
  const prevFrameChunksRef = React.useRef<
    readonly MarkdownGreenfieldChunkFrame[] | null
  >(null);
  const viewportHeight = viewportSize.height || DEFAULT_VIEWPORT_HEIGHT;
  const viewportWidth = viewportSize.width || DEFAULT_VIEWPORT_WIDTH;
  const measuredHeightLookup = React.useMemo(
    () => ({
      get: (
        chunk: MarkdownGreenfieldChunk,
        context: MarkdownGreenfieldMeasurementContext,
      ) =>
        measuredHeights.get(
          measuredHeightKey({
            chunk,
            context,
            documentMeasurementId,
          }),
        ),
      cacheKey: `${documentMeasurementId}:${measuredHeightsRevision}`,
    }),
    [documentMeasurementId, measuredHeights, measuredHeightsRevision],
  );
  const frame = React.useMemo(
    () =>
      layoutMarkdownGreenfieldDocument({
        contentWidth,
        document,
        fontScale,
        measuredHeights: measuredHeightLookup,
      }),
    [contentWidth, document, fontScale, measuredHeightLookup],
  );
  const highlightRange = React.useMemo(
    () => normalizeTextLineRange(highlight, document.lineCount),
    [document.lineCount, highlight],
  );
  const visibleHighlightRange = highlightRange;
  const visibleFrames = React.useMemo(
    () =>
      getMarkdownGreenfieldVisibleFrames({
        frames: frame.chunks,
        overscanPx: OVERSCAN_PX,
        scrollTop,
        viewportHeight,
      }),
    [frame.chunks, scrollTop, viewportHeight],
  );
  const captureAnchor = React.useCallback(() => {
    // Read the live scroll position from the DOM rather than the `scrollTop`
    // state, which lags behind during fast scrolling. Capturing a stale value
    // here makes the anchor-restore effect yank the viewport back to an old
    // (often near-top) position when a freshly revealed chunk is measured.
    const liveScrollTop =
      viewportRef.current?.scrollTop ?? scrollTopRef.current;
    pendingAnchorRef.current = getMarkdownGreenfieldScrollAnchor({
      frames: frame.chunks,
      scrollTop: liveScrollTop,
    });
  }, [frame.chunks]);

  const commitScrollTop = React.useCallback((nextScrollTop: number) => {
    scrollTopRef.current = nextScrollTop;
    setScrollTop(nextScrollTop);
  }, []);

  const scheduleScrollTop = React.useCallback(
    (nextScrollTop: number) => {
      scrollTopRef.current = nextScrollTop;
      if (scrollFrameRef.current !== null) return;
      if (typeof requestAnimationFrame !== "function") {
        commitScrollTop(scrollTopRef.current);
        return;
      }
      scrollFrameRef.current = requestAnimationFrame(() => {
        scrollFrameRef.current = null;
        commitScrollTop(scrollTopRef.current);
      });
    },
    [commitScrollTop],
  );

  const flushMeasuredHeights = React.useCallback(() => {
    measuredHeightFrameRef.current = null;
    const pending = pendingMeasuredHeightsRef.current;
    if (!pending.size) return;
    pendingMeasuredHeightsRef.current = new Map();
    setMeasuredHeights((current) => {
      let next: Map<string, number> | null = null;
      for (const [key, height] of pending) {
        if (Math.abs((current.get(key) ?? 0) - height) < 1) continue;
        next ??= new Map(current);
        next.set(key, height);
      }
      if (!next) return current;
      setMeasuredHeightsRevision((revision) => revision + 1);
      return next;
    });
  }, []);

  const scheduleMeasuredHeightsFlush = React.useCallback(() => {
    if (measuredHeightFrameRef.current !== null) return;
    if (typeof requestAnimationFrame !== "function") {
      flushMeasuredHeights();
      return;
    }
    measuredHeightFrameRef.current =
      requestAnimationFrame(flushMeasuredHeights);
  }, [flushMeasuredHeights]);

  React.useLayoutEffect(() => {
    setMeasuredHeights(new Map());
    setMeasuredHeightsRevision((revision) => revision + 1);
    commitScrollTop(0);
    viewportRef.current?.scrollTo({ left: 0, top: 0 });
  }, [commitScrollTop, document]);

  React.useEffect(
    () => () => {
      if (
        scrollFrameRef.current !== null &&
        typeof cancelAnimationFrame === "function"
      ) {
        cancelAnimationFrame(scrollFrameRef.current);
      }
      if (
        measuredHeightFrameRef.current !== null &&
        typeof cancelAnimationFrame === "function"
      ) {
        cancelAnimationFrame(measuredHeightFrameRef.current);
      }
    },
    [],
  );

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;

    const readSize = () => {
      setViewportSize((current) => {
        const next = {
          height: viewport.clientHeight,
          width: viewport.clientWidth,
        };
        return current.height === next.height && current.width === next.width
          ? current
          : next;
      });
    };

    readSize();
    const observer =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(readSize);
    observer?.observe(viewport);
    return () => observer?.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const nextWidth = Math.max(
      1,
      viewportWidth - VIEWER_HORIZONTAL_PADDING * 2,
    );
    setContentWidth((current) => {
      if (current === nextWidth) return current;
      captureAnchor();
      return nextWidth;
    });
  }, [captureAnchor, viewportWidth]);

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current;
    const previousChunks = prevFrameChunksRef.current;
    prevFrameChunksRef.current = frame.chunks;
    if (!viewport) return;

    // Intentional full reflows (width, zoom, font readiness, mode switch) set an
    // explicit anchor and want to restore the reader's relative position.
    const anchor = pendingAnchorRef.current;
    if (anchor) {
      pendingAnchorRef.current = null;
      const nextScrollTop = resolveMarkdownGreenfieldScrollAnchor({
        anchor,
        frames: frame.chunks,
      });
      if (nextScrollTop == null) return;
      viewport.scrollTop = nextScrollTop;
      commitScrollTop(nextScrollTop);
      return;
    }

    // Measurement-driven changes keep whatever the reader is looking at stable by
    // compensating scrollTop for the height delta of chunks ENTIRELY above the
    // viewport top. Only already-measured chunks (real height in both layouts)
    // count: a chunk's first estimate->measured correction happens as it is
    // revealed near/below the viewport, never while the reader sits above it, so
    // excluding it avoids the estimate-collapse plunge while still pinning the
    // viewport when async rich blocks above re-settle.
    if (!previousChunks) return;
    const liveScrollTop = viewport.scrollTop;
    const previousById = new Map(
      previousChunks.map((chunkFrame) => [chunkFrame.id, chunkFrame]),
    );
    let delta = 0;
    for (const chunkFrame of frame.chunks) {
      const previous = previousById.get(chunkFrame.id);
      if (
        previous &&
        previous.measuredHeight != null &&
        chunkFrame.measuredHeight != null &&
        previous.bottom <= liveScrollTop
      ) {
        delta += chunkFrame.measuredHeight - previous.measuredHeight;
      }
    }
    if (delta === 0) return;
    const nextScrollTop = Math.max(0, liveScrollTop + delta);
    viewport.scrollTop = nextScrollTop;
    commitScrollTop(nextScrollTop);
  }, [commitScrollTop, frame.chunks]);

  const scrollToLineRange = React.useCallback(
    (
      range: ReturnType<typeof normalizeTextLineRange>,
      options?: MarkdownScrollToLineOptions,
    ) => {
      const viewport = viewportRef.current;
      if (!viewport || !range) return;

      const preferredChunkId =
        options?.preferredChunkId ??
        findMarkdownGreenfieldChunkBySourceLine(document, range.start)?.id;
      const top = getMarkdownGreenfieldScrollTopForLineRange({
        chunks: document.chunks,
        frames: frame.chunks,
        preferredChunkId,
        range,
        viewportHeight: viewport.clientHeight || viewportHeight,
      });
      if (top == null) return;
      viewport.scrollTo({
        behavior: resolveScrollBehavior(options?.behavior),
        left: options?.left,
        top,
      });
      commitScrollTop(top);
    },
    [commitScrollTop, document, frame.chunks, viewportHeight],
  );

  // A stable handle to the latest scrollToLineRange. The callback's identity
  // changes on every layout change (its deps include frame.chunks), so effects
  // that should fire only when their *target* changes must not depend on it
  // directly — otherwise each measurement re-runs them and yanks the viewport
  // back to the highlight/search/hash target while the reader is scrolling.
  const scrollToLineRangeRef = React.useRef(scrollToLineRange);
  React.useLayoutEffect(() => {
    scrollToLineRangeRef.current = scrollToLineRange;
  }, [scrollToLineRange]);

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      getViewportElement: () => viewportRef.current,
      scrollToLineRange: (range, options) => {
        scrollToLineRangeRef.current(
          normalizeTextLineRange(range, document.lineCount),
          options,
        );
      },
    }),
    [document.lineCount],
  );

  // Scrolling is an imperative DOM mutation that must run before paint to avoid
  // a visible jump, so these reactions to a changed target line/range live in
  // layout effects, not useEffect.
  React.useLayoutEffect(() => {
    if (!highlightRange) return;
    scrollToLineRangeRef.current(highlightRange);
  }, [highlightRange]);

  // Subscribes to the browser's hash/history (a non-React external source) and
  // scrolls the matching fragment into view before paint.
  React.useLayoutEffect(() => {
    if (!urlFragmentNavigation) return;

    const scrollToCurrentHash = () => {
      const hash = window.location.hash;
      if (!hash) return;
      const target = findMarkdownGreenfieldFragmentTargetById(document, hash);
      if (!target) return;
      const chunk = findMarkdownGreenfieldChunkByBlockId(
        document,
        target.blockId,
      );
      scrollToLineRangeRef.current(
        normalizeTextLineRange(
          { end: target.sourceLine, start: target.sourceLine },
          document.lineCount,
        ),
        { behavior: "auto", preferredChunkId: chunk?.id },
      );
    };

    scrollToCurrentHash();
    window.addEventListener("hashchange", scrollToCurrentHash);
    window.addEventListener("popstate", scrollToCurrentHash);
    return () => {
      window.removeEventListener("hashchange", scrollToCurrentHash);
      window.removeEventListener("popstate", scrollToCurrentHash);
    };
  }, [document, urlFragmentNavigation]);

  const recordMeasuredHeight = React.useCallback(
    (chunk: MarkdownGreenfieldChunk, height: number) => {
      if (!Number.isFinite(height) || height <= 0) return;
      const key = measuredHeightKey({
        chunk,
        context: {
          fontScale,
          policyVersion: MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
          width: Math.max(1, contentWidth),
        },
        documentMeasurementId,
      });
      pendingMeasuredHeightsRef.current.set(key, height);
      scheduleMeasuredHeightsFlush();
    },
    [
      contentWidth,
      documentMeasurementId,
      fontScale,
      scheduleMeasuredHeightsFlush,
    ],
  );
  const handleDownloadError = React.useCallback<ViewerDownloadErrorHandler>(
    (error) => {
      if (error.kind === "aborted") return;
      setDownloadError(error.message || "Could not download Markdown.");
    },
    [],
  );
  const zoom = (factor: number) => {
    captureAnchor();
    setFontScale((scale) => clampTextViewerScale(scale * factor));
  };
  const resetZoom = () => {
    captureAnchor();
    setFontScale(1);
  };

  return (
    <TextViewerFrame className={className} bare={bare}>
      {controls ? (
        <TextViewerControls
          downloadAction={downloadAction}
          extra={<DownloadError message={downloadError} />}
          fontScale={fontScale}
          wordCount={
            isDocumentPending
              ? estimateMarkdownWordCount(text)
              : document.wordCount
          }
          onDownloadError={handleDownloadError}
          onResetZoom={resetZoom}
          onZoomIn={() => zoom(1.2)}
          onZoomOut={() => zoom(1 / 1.2)}
        />
      ) : null}
      {/* overflow-anchor:none disables the browser's native scroll anchoring,
          which otherwise fights this component's virtualization: as chunks
          mount/unmount and the canvas height corrects, the browser shifts
          scrollTop on its own, jerking the viewport while the reader scrolls. */}
      <ScrollArea
        className="bg-background min-h-0 flex-1"
        orientation="vertical"
        viewportClassName="bg-background [overflow-anchor:none]"
        viewportRef={viewportRef}
        viewportProps={{
          onClickCapture: (event) =>
            handleRenderedClick({ document, event, scrollToLineRange }),
          onScroll: (event) => scheduleScrollTop(event.currentTarget.scrollTop),
        }}
      >
        <div
          className="relative min-w-0"
          data-projection="unified-hast-markdown"
          data-slot="markdown-virtual-canvas"
          style={{
            height: Math.max(frame.totalHeight, viewportHeight),
            minWidth: viewportWidth,
          }}
        >
          {isDocumentPending ? null : (
            <DeferredNativeFindIndex
              chunks={document.chunks}
              lineCount={document.lineCount}
              scrollToLineRange={scrollToLineRange}
            />
          )}
          {isDocumentPending ? (
            <div
              aria-label="Preparing Markdown document"
              className="text-muted-foreground absolute inset-x-4 top-0 flex min-h-40 items-center justify-center text-sm"
              data-slot="markdown-loading-state"
              role="status"
            >
              Preparing Markdown...
            </div>
          ) : document.text.trim() ? (
            visibleFrames.map((chunkFrame) => {
              const chunk = document.chunks[chunkFrame.index];
              if (!chunk) return null;
              return (
                <ChunkFrame
                  key={chunk.id}
                  chunk={chunk}
                  frame={chunkFrame}
                  highlightRange={visibleHighlightRange}
                  highlighted={chunkIntersectsLineRange({
                    chunkFrame,
                    range: visibleHighlightRange,
                  })}
                  measurementKey={measuredHeightKey({
                    chunk,
                    context: {
                      fontScale,
                      policyVersion: MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
                      width: Math.max(1, contentWidth),
                    },
                    documentMeasurementId,
                  })}
                  onMeasuredHeight={recordMeasuredHeight}
                >
                  <MarkdownGreenfieldChunkRenderer
                    chunk={chunk}
                    fontScale={fontScale}
                    urlFragmentNavigation={urlFragmentNavigation}
                  />
                </ChunkFrame>
              );
            })
          ) : (
            <div
              aria-label="Empty Markdown document"
              className="text-muted-foreground absolute inset-x-4 top-0 flex min-h-40 items-center justify-center text-sm"
              data-slot="markdown-empty-state"
              role="status"
            >
              Empty Markdown document
            </div>
          )}
        </div>
      </ScrollArea>
    </TextViewerFrame>
  );
}

function DeferredNativeFindIndex({
  chunks,
  lineCount,
  scrollToLineRange,
}: {
  chunks: readonly MarkdownGreenfieldChunk[];
  lineCount: number;
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: MarkdownScrollToLineOptions,
  ) => void;
}) {
  const [isReady, setIsReady] = React.useState(false);

  React.useEffect(() => {
    setIsReady(false);
    const show = () => setIsReady(true);
    if (typeof window === "undefined") return;
    const browserWindow = window as MarkdownIdleWindow;
    if (browserWindow.requestIdleCallback && browserWindow.cancelIdleCallback) {
      const idleId = browserWindow.requestIdleCallback(show, { timeout: 400 });
      return () => browserWindow.cancelIdleCallback?.(idleId);
    }
    const timeoutId = browserWindow.setTimeout(show, 80);
    return () => browserWindow.clearTimeout(timeoutId);
  }, [chunks]);

  if (!isReady) return null;
  return (
    <NativeFindIndex
      chunks={chunks}
      lineCount={lineCount}
      scrollToLineRange={scrollToLineRange}
    />
  );
}

function NativeFindIndex({
  chunks,
  lineCount,
  scrollToLineRange,
}: {
  chunks: readonly MarkdownGreenfieldChunk[];
  lineCount: number;
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: MarkdownScrollToLineOptions,
  ) => void;
}) {
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute top-0 left-0 h-px w-px overflow-hidden opacity-0"
      data-slot="markdown-native-find-index"
    >
      {chunks.map((chunk) => (
        <NativeFindEntry
          key={chunk.id}
          chunk={chunk}
          lineCount={lineCount}
          scrollToLineRange={scrollToLineRange}
        />
      ))}
    </div>
  );
}

function NativeFindEntry({
  chunk,
  lineCount,
  scrollToLineRange,
}: {
  chunk: MarkdownGreenfieldChunk;
  lineCount: number;
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: MarkdownScrollToLineOptions,
  ) => void;
}) {
  const ref = React.useRef<HTMLSpanElement | null>(null);
  const text = nativeFindTextForChunk(chunk);

  React.useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    element.setAttribute("hidden", "until-found");

    const handleBeforeMatch = () => {
      scrollToLineRange(
        normalizeTextLineRange(
          {
            end: chunk.sourceEndLine,
            start: chunk.sourceStartLine,
          },
          lineCount,
        ),
        { behavior: "auto", preferredChunkId: chunk.id },
      );
      requestAnimationFrame(() => {
        element.setAttribute("hidden", "until-found");
      });
    };

    element.addEventListener("beforematch", handleBeforeMatch);
    return () => {
      element.removeEventListener("beforematch", handleBeforeMatch);
    };
  }, [
    chunk.id,
    chunk.sourceEndLine,
    chunk.sourceStartLine,
    lineCount,
    scrollToLineRange,
  ]);

  return (
    <span
      ref={ref}
      className="absolute top-0 left-0 block h-px w-px overflow-hidden whitespace-pre"
      data-native-find-chunk-id={chunk.id}
      data-native-find-end-line={chunk.sourceEndLine}
      data-native-find-start-line={chunk.sourceStartLine}
    >
      {text || " "}
    </span>
  );
}

function nativeFindTextForChunk(chunk: MarkdownGreenfieldChunk) {
  return chunk.hastChildren.map(nativeFindTextForHastNode).join(" ").trim();
}

function nativeFindTextForHastNode(node: MarkdownHastNode): string {
  if (node.type === "text" && typeof node.value === "string") return node.value;
  const element = node as MarkdownHastElement;
  if (!element || element.type !== "element") return "";

  if (element.tagName === "script" || element.tagName === "style") return "";
  return element.children.map(nativeFindTextForHastNode).join(" ");
}

function DownloadError({ message }: { message: string }) {
  if (!message) return null;
  return (
    <span
      className="text-destructive max-w-48 truncate text-xs"
      data-slot="markdown-download-error"
      role="status"
    >
      {message}
    </span>
  );
}

function ChunkFrame({
  children,
  chunk,
  frame,
  highlightRange,
  highlighted,
  measurementKey,
  onMeasuredHeight,
}: {
  children: React.ReactNode;
  chunk: MarkdownGreenfieldChunk;
  frame: MarkdownGreenfieldChunkFrame;
  highlightRange: { end: number; start: number } | null;
  highlighted: boolean;
  measurementKey: string;
  onMeasuredHeight: (chunk: MarkdownGreenfieldChunk, height: number) => void;
}) {
  const ref = React.useRef<HTMLDivElement | null>(null);

  React.useLayoutEffect(() => {
    measure();
    const element = ref.current;
    if (!element || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();

    function measure() {
      const element = ref.current;
      if (!element) return;
      onMeasuredHeight(chunk, element.getBoundingClientRect().height);
    }
  }, [chunk, onMeasuredHeight]);

  return (
    <section
      ref={ref}
      aria-label={
        highlighted
          ? `Highlighted source lines ${highlightRange?.start}-${highlightRange?.end}`
          : `Markdown lines ${frame.sourceStartLine} to ${frame.sourceEndLine}`
      }
      className={[
        "absolute left-1/2 w-full max-w-4xl -translate-x-1/2 px-8 py-1",
      ].join(" ")}
      data-markdown-chunk=""
      data-markdown-highlighted={highlighted ? "" : undefined}
      data-pretext-measured-height-key={measurementKey}
      data-source-highlight-end={highlighted ? highlightRange?.end : undefined}
      data-source-highlight-start={
        highlighted ? highlightRange?.start : undefined
      }
      data-source-end-line={frame.sourceEndLine}
      data-source-start-line={frame.sourceStartLine}
      role={highlighted ? "region" : undefined}
      style={{
        top: frame.top,
        ...(highlighted ? MARKDOWN_GREENFIELD_HIGHLIGHT_STYLE : null),
      }}
    >
      {children}
    </section>
  );
}

function resolveScrollBehavior(behavior: ScrollBehavior | undefined) {
  if (behavior) return behavior;
  if (
    typeof window !== "undefined" &&
    window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
  ) {
    return "auto";
  }
  return "smooth";
}

function handleRenderedClick({
  document,
  event,
  scrollToLineRange,
}: {
  document: ReturnType<typeof createMarkdownGreenfieldDocument>;
  event: React.MouseEvent;
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: MarkdownScrollToLineOptions,
  ) => void;
}) {
  const link = (event.target as HTMLElement | null)?.closest("a[href]");
  const href = link?.getAttribute("href");
  if (!href?.startsWith("#")) return;

  const target = findMarkdownGreenfieldFragmentTargetById(document, href);
  if (!target) return;
  const chunk = findMarkdownGreenfieldChunkByBlockId(document, target.blockId);

  event.preventDefault();
  window.history.pushState(null, "", href);
  scrollToLineRange(
    normalizeTextLineRange(
      { end: target.sourceLine, start: target.sourceLine },
      document.lineCount,
    ),
    { behavior: "smooth", preferredChunkId: chunk?.id },
  );
}

function chunkIntersectsLineRange({
  chunkFrame,
  range,
}: {
  chunkFrame: MarkdownGreenfieldChunkFrame;
  range: { end: number; start: number } | null;
}) {
  if (!range) return false;
  return (
    chunkFrame.sourceStartLine <= range.end &&
    chunkFrame.sourceEndLine >= range.start
  );
}

function measuredHeightKey({
  chunk,
  context,
  documentMeasurementId,
}: {
  chunk: MarkdownGreenfieldChunk;
  context: MarkdownGreenfieldMeasurementContext;
  documentMeasurementId: string;
}) {
  return [
    documentMeasurementId,
    chunk.id,
    Math.round(context.width),
    context.fontScale.toFixed(4),
    context.policyVersion,
  ].join(":");
}

function measurementDocumentIdForText(text: string) {
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `md-${text.length}-${(hash >>> 0).toString(36)}`;
}

function estimateMarkdownWordCount(text: string) {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

"use client";

import * as React from "react";

export function isSafeHighlightedCodeLine(line: number) {
  return Number.isInteger(line) && line > 0 && line <= 100_000;
}

export function normalizeCodeLanguage(language: string | null) {
  const value = (language ?? "text").toLowerCase();
  const aliases: Record<string, string> = {
    bash: "shell",
    docker: "dockerfile",
    javascript: "js",
    jsonc: "json",
    md: "markdown",
    patch: "diff",
    rb: "ruby",
    "shell-session": "shell",
    terminal: "shell",
    typescript: "ts",
    yml: "yaml",
  };
  return aliases[value] ?? value;
}

export function diffLineKind(line: string) {
  if (line.startsWith("+") && !line.startsWith("+++")) return "add";
  if (line.startsWith("-") && !line.startsWith("---")) return "remove";
  return null;
}

export function renderCodeLine({
  fallbackLanguage,
  line,
  pattern,
  shikiLine,
}: {
  fallbackLanguage: string;
  line: string;
  pattern: string;
  shikiLine: readonly ShikiCodeToken[] | undefined;
}) {
  if (shikiLine) {
    return renderShikiCodeLine({
      fallbackLanguage,
      line,
      pattern,
      tokens: shikiLine,
    });
  }
  if (!pattern) return renderFallbackCodeTokens(line || " ", fallbackLanguage);
  const index = line.indexOf(pattern);
  if (index < 0) return renderFallbackCodeTokens(line || " ", fallbackLanguage);
  return (
    <>
      {renderFallbackCodeTokens(line.slice(0, index), fallbackLanguage)}
      <span data-highlighted-chars="">{pattern}</span>
      {renderFallbackCodeTokens(
        line.slice(index + pattern.length),
        fallbackLanguage,
      )}
    </>
  );
}

function renderShikiCodeLine({
  fallbackLanguage,
  line,
  pattern,
  tokens,
}: {
  fallbackLanguage: string;
  line: string;
  pattern: string;
  tokens: readonly ShikiCodeToken[];
}) {
  if (!tokens.length) return " ";
  if (!pattern) return renderShikiCodeTokens(tokens);

  const highlightStart = line.indexOf(pattern);
  if (highlightStart < 0) return renderShikiCodeTokens(tokens);

  return renderShikiCodeTokensWithHighlight({
    fallbackLanguage,
    highlightEnd: highlightStart + pattern.length,
    highlightStart,
    tokens,
  });
}

function renderShikiCodeTokens(tokens: readonly ShikiCodeToken[]) {
  return tokens.map((token, index) => (
    <span
      key={index}
      className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
      data-pretext-code-token="shiki"
      data-shiki-token=""
      style={shikiTokenStyle(token)}
    >
      {token.content}
    </span>
  ));
}

function renderShikiCodeTokensWithHighlight({
  fallbackLanguage,
  highlightEnd,
  highlightStart,
  tokens,
}: {
  fallbackLanguage: string;
  highlightEnd: number;
  highlightStart: number;
  tokens: readonly ShikiCodeToken[];
}) {
  const rendered: React.ReactNode[] = [];
  let cursor = 0;

  tokens.forEach((token, tokenIndex) => {
    const tokenStart = cursor;
    const tokenEnd = cursor + token.content.length;
    cursor = tokenEnd;

    if (tokenEnd <= highlightStart || tokenStart >= highlightEnd) {
      rendered.push(
        <span
          key={tokenIndex}
          className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
          data-pretext-code-token="shiki"
          data-shiki-token=""
          style={shikiTokenStyle(token)}
        >
          {token.content}
        </span>,
      );
      return;
    }

    const before = token.content.slice(
      0,
      Math.max(0, highlightStart - tokenStart),
    );
    const highlighted = token.content.slice(
      Math.max(0, highlightStart - tokenStart),
      Math.min(token.content.length, highlightEnd - tokenStart),
    );
    const after = token.content.slice(
      Math.min(token.content.length, highlightEnd - tokenStart),
    );

    if (before) {
      rendered.push(
        <span
          key={`${tokenIndex}-before`}
          className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
          data-pretext-code-token="shiki"
          data-shiki-token=""
          style={shikiTokenStyle(token)}
        >
          {before}
        </span>,
      );
    }
    if (highlighted) {
      rendered.push(
        <span key={`${tokenIndex}-highlight`} data-highlighted-chars="">
          <span
            className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
            data-pretext-code-token="shiki"
            data-shiki-token=""
            style={shikiTokenStyle(token)}
          >
            {highlighted}
          </span>
        </span>,
      );
    }
    if (after) {
      rendered.push(
        <span
          key={`${tokenIndex}-after`}
          className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
          data-pretext-code-token="shiki"
          data-shiki-token=""
          style={shikiTokenStyle(token)}
        >
          {after}
        </span>,
      );
    }
  });

  if (rendered.length) return rendered;
  return renderFallbackCodeTokens(" ", fallbackLanguage);
}

function renderFallbackCodeTokens(line: string, language: string) {
  const tokens = tokenizeCodeLine(line, language);
  if (!tokens.length) return " ";
  return tokens.map((token, index) =>
    token.kind === "plain" ? (
      <React.Fragment key={index}>{token.value}</React.Fragment>
    ) : (
      <span
        key={index}
        className={codeTokenClassName(token.kind)}
        data-pretext-code-token={token.kind}
      >
        {token.value}
      </span>
    ),
  );
}

type ShikiCodeToken = {
  content: string;
  darkColor: string;
  fontStyle: number | undefined;
  lightColor: string;
};

type RawShikiToken = {
  content?: unknown;
  variants?: {
    dark?: {
      color?: unknown;
      fontStyle?: unknown;
    };
    light?: {
      color?: unknown;
      fontStyle?: unknown;
    };
  };
};

const shikiCodeLineCache = new Map<
  string,
  Promise<ShikiCodeToken[][] | null>
>();
const resolvedShikiCodeLines = new Map<string, ShikiCodeToken[][] | null>();
const shikiCodeLineSubscribersByKey = new Map<string, Set<() => void>>();

function ensureShikiCodeLines(args: {
  cacheKey: string;
  expectedLineCount: number;
  language: string;
  source: string;
}) {
  if (resolvedShikiCodeLines.has(args.cacheKey)) return;
  void getShikiCodeLines(args).then((lines) => {
    resolvedShikiCodeLines.set(args.cacheKey, lines);
    while (resolvedShikiCodeLines.size > 128) {
      const oldestKey = resolvedShikiCodeLines.keys().next().value;
      if (oldestKey === undefined) break;
      resolvedShikiCodeLines.delete(oldestKey);
    }
    notifyShikiCodeLineSubscribers(args.cacheKey);
  });
}

// Shiki tokenization is an asynchronous external system (a dynamically imported
// highlighter with a shared resolved-value cache). The viewer subscribes to
// that cache with useSyncExternalStore — the React-idiomatic way to read an
// external store — rather than driving the load from an effect. The snapshot
// returns a stable reference (the cached array, or null while pending) so
// rendering stays progressive: plain source first, highlighted once resolved.
export function useShikiCodeLines(
  source: string,
  language: string,
  expectedLineCount: number,
) {
  const cacheKey = `${language}\0${source}`;
  const subscribe = React.useCallback(
    (onStoreChange: () => void) => {
      const subscribers =
        shikiCodeLineSubscribersByKey.get(cacheKey) ?? new Set();
      subscribers.add(onStoreChange);
      shikiCodeLineSubscribersByKey.set(cacheKey, subscribers);
      ensureShikiCodeLines({ cacheKey, expectedLineCount, language, source });
      return () => {
        subscribers.delete(onStoreChange);
        if (!subscribers.size) shikiCodeLineSubscribersByKey.delete(cacheKey);
      };
    },
    [cacheKey, expectedLineCount, language, source],
  );
  const getSnapshot = React.useCallback(
    () =>
      resolvedShikiCodeLines.has(cacheKey)
        ? (resolvedShikiCodeLines.get(cacheKey) ?? null)
        : null,
    [cacheKey],
  );
  return React.useSyncExternalStore(subscribe, getSnapshot, () => null);
}

function notifyShikiCodeLineSubscribers(cacheKey: string) {
  const subscribers = shikiCodeLineSubscribersByKey.get(cacheKey);
  if (!subscribers) return;
  for (const notify of subscribers) notify();
}

function getShikiCodeLines({
  cacheKey,
  expectedLineCount,
  language,
  source,
}: {
  cacheKey: string;
  expectedLineCount: number;
  language: string;
  source: string;
}) {
  let cached = shikiCodeLineCache.get(cacheKey);
  if (!cached) {
    cached = loadShikiCodeLines({ expectedLineCount, language, source });
    shikiCodeLineCache.set(cacheKey, cached);
    trimShikiCodeLineCache();
  }
  return cached;
}

async function loadShikiCodeLines({
  expectedLineCount,
  language,
  source,
}: {
  expectedLineCount: number;
  language: string;
  source: string;
}) {
  try {
    const shiki = await import("shiki");
    const lines = (await (shiki.codeToTokensWithThemes as any)(source, {
      lang: shikiLanguageFor(language),
      themes: {
        dark: "github-dark",
        light: "github-light-default",
      },
    })) as RawShikiToken[][];

    return normalizeShikiCodeLines(lines, expectedLineCount);
  } catch {
    return null;
  }
}

function normalizeShikiCodeLines(
  lines: RawShikiToken[][],
  expectedLineCount: number,
) {
  return Array.from({ length: expectedLineCount }, (_, index) =>
    normalizeShikiCodeLine(lines[index] ?? []),
  );
}

function normalizeShikiCodeLine(tokens: RawShikiToken[]): ShikiCodeToken[] {
  return tokens
    .map((token) => {
      const content = typeof token.content === "string" ? token.content : "";
      const lightColor = readShikiTokenColor(token, "light");
      const darkColor = readShikiTokenColor(token, "dark");
      if (!content || !lightColor || !darkColor) return null;
      return {
        content,
        darkColor,
        fontStyle: readShikiTokenFontStyle(token),
        lightColor,
      };
    })
    .filter((token): token is ShikiCodeToken => token != null);
}

function readShikiTokenColor(token: RawShikiToken, variant: "dark" | "light") {
  const color = token.variants?.[variant]?.color;
  return typeof color === "string" && /^#[0-9a-f]{6,8}$/i.test(color)
    ? color
    : "";
}

function readShikiTokenFontStyle(token: RawShikiToken) {
  const fontStyle =
    typeof token.variants?.light?.fontStyle === "number"
      ? token.variants.light.fontStyle
      : undefined;
  return fontStyle && Number.isFinite(fontStyle) ? fontStyle : undefined;
}

function shikiTokenStyle(token: ShikiCodeToken) {
  return {
    "--shiki-dark": token.darkColor,
    "--shiki-light": token.lightColor,
    fontStyle: token.fontStyle === 1 ? "italic" : undefined,
  } as React.CSSProperties;
}

function shikiLanguageFor(language: string) {
  const aliases: Record<string, string> = {
    dockerfile: "docker",
    js: "javascript",
    shell: "bash",
    ts: "typescript",
  };
  return aliases[language] ?? language;
}

function trimShikiCodeLineCache() {
  while (shikiCodeLineCache.size > 64) {
    const oldestKey = shikiCodeLineCache.keys().next().value;
    if (!oldestKey) break;
    shikiCodeLineCache.delete(oldestKey);
  }
}

type CodeToken = {
  kind: "comment" | "keyword" | "literal" | "number" | "plain" | "string";
  value: string;
};

function tokenizeCodeLine(line: string, language: string): CodeToken[] {
  if (!line) return [];
  if (language === "diff") return tokenizeDiffLine(line);
  if (language === "json") return tokenizeJsonLikeLine(line);
  if (language === "yaml") return tokenizeYamlLine(line);
  if (
    language === "js" ||
    language === "jsx" ||
    language === "ts" ||
    language === "tsx"
  ) {
    return tokenizeCStyleLine(line);
  }
  if (
    language === "shell" ||
    language === "bash" ||
    language === "dockerfile"
  ) {
    return tokenizeShellLine(line);
  }
  return [{ kind: "plain", value: line }];
}

function tokenizeCStyleLine(line: string): CodeToken[] {
  const commentIndex = line.indexOf("//");
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : "";
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:as|async|await|break|case|catch|class|const|continue|default|do|else|export|extends|false|finally|for|from|function|if|import|in|instanceof|interface|let|new|null|of|return|satisfies|switch|throw|true|try|type|typeof|undefined|var|while|yield)\b|\b\d+(?:\.\d+)?\b)/g,
      classifyCStyleToken,
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ];
}

function classifyCStyleToken(value: string): CodeToken["kind"] {
  if (/^["'`]/.test(value)) return "string";
  if (/^\d/.test(value)) return "number";
  if (/^(?:true|false|null|undefined)$/.test(value)) return "literal";
  return "keyword";
}

function tokenizeJsonLikeLine(line: string): CodeToken[] {
  return tokenizeByPattern(
    line,
    /("(?:\\.|[^"\\])*"|\b(?:true|false|null)\b|-?\b\d+(?:\.\d+)?(?:e[+-]?\d+)?\b)/gi,
    (value) => {
      if (/^"/.test(value)) return "string";
      if (/^(?:true|false|null)$/i.test(value)) return "literal";
      return "number";
    },
  );
}

function tokenizeYamlLine(line: string): CodeToken[] {
  const commentIndex = line.indexOf("#");
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : "";
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:true|false|null)\b|-?\b\d+(?:\.\d+)?\b)/gi,
      (value) => {
        if (/^["']/.test(value)) return "string";
        if (/^(?:true|false|null)$/i.test(value)) return "literal";
        return "number";
      },
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ];
}

function tokenizeShellLine(line: string): CodeToken[] {
  const commentIndex = line.search(/(^|\s)#/);
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : "";
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:cd|cp|curl|echo|export|git|grep|mkdir|mv|node|npm|pnpm|rm|sed|test|yarn)\b)/g,
      (value) => (/^["']/.test(value) ? "string" : "keyword"),
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ];
}

function tokenizeDiffLine(line: string): CodeToken[] {
  if (line.startsWith("+") && !line.startsWith("+++")) {
    return [{ kind: "literal", value: line }];
  }
  if (line.startsWith("-") && !line.startsWith("---")) {
    return [{ kind: "comment", value: line }];
  }
  return [{ kind: "plain", value: line }];
}

function tokenizeByPattern(
  line: string,
  pattern: RegExp,
  classify: (value: string) => CodeToken["kind"],
): CodeToken[] {
  const tokens: CodeToken[] = [];
  let cursor = 0;
  for (const match of line.matchAll(pattern)) {
    const index = match.index ?? 0;
    if (index > cursor) {
      tokens.push({ kind: "plain", value: line.slice(cursor, index) });
    }
    const value = match[0];
    tokens.push({ kind: classify(value), value });
    cursor = index + value.length;
  }
  if (cursor < line.length) {
    tokens.push({ kind: "plain", value: line.slice(cursor) });
  }
  return tokens;
}

function codeTokenClassName(kind: CodeToken["kind"]) {
  switch (kind) {
    case "comment":
      return "text-muted-foreground italic";
    case "keyword":
      return "font-semibold text-sky-700 dark:text-sky-300";
    case "literal":
      return "text-purple-700 dark:text-purple-300";
    case "number":
      return "text-amber-700 dark:text-amber-300";
    case "string":
      return "text-emerald-700 dark:text-emerald-300";
    default:
      return "";
  }
}

"use client";

/* eslint-disable no-restricted-syntax -- TODO(no-useEffect): existing direct React effect usage; migrate to useMountEffect or a Rule 1-5 replacement. */

import * as React from "react";
import { Check, Clipboard } from "lucide-react";

const MERMAID_MAX_LINES = 160;
const MERMAID_MAX_SOURCE_LENGTH = 12_000;

const MERMAID_CONFIG = {
  flowchart: {
    htmlLabels: false,
    useMaxWidth: true,
  },
  securityLevel: "strict",
  sequence: {
    useMaxWidth: true,
  },
  startOnLoad: false,
  suppressErrorRendering: true,
  theme: "default",
} as const;

const mermaidDiagramCache = new Map<string, Promise<DiagramState>>();

type DiagramState =
  | { status: "failed"; message: string }
  | { status: "loading" }
  | { status: "ready"; svg: string };
type ReadyDiagramState = Extract<DiagramState, { status: "ready" }>;

// A per-instance async store for one diagram's mermaid render. Kept per
// component (not module-global) so instances never share state — no cross-
// render notify fan-out and no shared cache keyed by a render-order id.
type MermaidDiagramStore = {
  key: string;
  result: DiagramState | null;
  listeners: Set<() => void>;
};

export function MarkdownGreenfieldDiagram({
  caption,
  componentName,
  onContentReady,
  source,
  title,
}: {
  caption?: string;
  componentName?: string;
  onContentReady?: () => void;
  source: string;
  title?: string;
}) {
  const limitMessage = React.useMemo(
    () => readDiagramLimitMessage(source),
    [source],
  );
  const diagramId = React.useId().replace(/:/g, "");
  const elementId = `markdown-diagram-${diagramId}`;
  const description = React.useMemo(() => describeDiagram(source), [source]);
  const bodyHeight = React.useMemo(
    () => estimateDiagramBodyHeight(source),
    [source],
  );
  const descriptionId = description
    ? `markdown-diagram-description-${diagramId}`
    : undefined;
  const captionId = caption
    ? `markdown-diagram-caption-${diagramId}`
    : undefined;
  const describedBy =
    [descriptionId, captionId].filter(Boolean).join(" ") || undefined;

  // Derive the displayed state: a limit message fails immediately; otherwise the
  // state follows this instance's async mermaid store (loading until resolved).
  const storeRef = React.useRef<MermaidDiagramStore | null>(null);
  if (storeRef.current === null) {
    storeRef.current = { key: "", listeners: new Set(), result: null };
  }
  const store = storeRef.current;
  const renderKey = limitMessage ? "" : `${elementId}\0${source}`;
  const subscribe = React.useCallback(
    (onStoreChange: () => void) => {
      store.listeners.add(onStoreChange);
      // Kick off (or restart on source change) the render here, in the store
      // subscription, so no effect is needed.
      if (!limitMessage && store.key !== renderKey) {
        store.key = renderKey;
        store.result = null;
        void renderMermaidDiagram(source, elementId).then((result) => {
          if (store.key !== renderKey) return;
          store.result = result;
          for (const listener of store.listeners) listener();
        });
      }
      return () => {
        store.listeners.delete(onStoreChange);
      };
    },
    [elementId, limitMessage, renderKey, source, store],
  );
  const getSnapshot = React.useCallback(
    () => (store.key === renderKey ? store.result : null),
    [renderKey, store],
  );
  const resolvedState = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    () => null,
  );
  const state: DiagramState = limitMessage
    ? { status: "failed", message: limitMessage }
    : (resolvedState ?? { status: "loading" });

  React.useLayoutEffect(() => {
    onContentReady?.();
  }, [bodyHeight, onContentReady, state.status]);

  return (
    <figure
      aria-describedby={describedBy}
      aria-label={title || "Mermaid diagram"}
      className="group bg-muted/30 my-5 min-h-40 overflow-hidden rounded-md border"
      data-diagram-language="mermaid"
      data-diagram-reserved-height={bodyHeight}
      data-diagram-state={state.status}
      data-pretext-component={componentName}
      role="group"
      style={
        {
          "--pretext-diagram-body-height": `${bodyHeight}px`,
        } as React.CSSProperties
      }
    >
      <div className="bg-muted/60 flex h-9 items-center gap-1 border-b px-3">
        <span className="text-muted-foreground min-w-0 truncate text-xs font-medium">
          {title || "mermaid"}
        </span>
        <DiagramCopyButton
          ariaLabel="Copy diagram source"
          className="ml-auto"
          text={source}
        />
        {state.status === "ready" ? (
          <DiagramCopyButton ariaLabel="Copy diagram SVG" text={state.svg} />
        ) : null}
      </div>
      {description ? (
        <p
          className="sr-only"
          data-pretext-diagram-description=""
          id={descriptionId}
        >
          {description}
        </p>
      ) : null}
      <div
        aria-label="Mermaid diagram body"
        className="h-(--pretext-diagram-body-height) overflow-auto p-4"
        data-pretext-diagram-body=""
        onKeyDown={(event) => {
          const element = event.currentTarget;
          if (event.key === "ArrowRight") {
            element.scrollLeft += 50;
            event.preventDefault();
          } else if (event.key === "ArrowLeft") {
            element.scrollLeft -= 50;
            event.preventDefault();
          } else if (event.key === "End") {
            element.scrollLeft = Math.max(
              0,
              element.scrollWidth - element.clientWidth,
            );
            event.preventDefault();
          } else if (event.key === "Home") {
            element.scrollLeft = 0;
            event.preventDefault();
          }
        }}
        role="region"
        tabIndex={0}
      >
        {state.status === "ready" ? (
          <div dangerouslySetInnerHTML={{ __html: state.svg }} />
        ) : (
          <>
            {state.status === "failed" ? (
              <p
                className="border-destructive/25 bg-destructive/10 text-destructive mb-3 rounded border px-3 py-2 text-sm"
                data-pretext-diagram-error=""
                role="alert"
              >
                {state.message}
              </p>
            ) : null}
            <pre
              aria-label="Mermaid diagram source"
              className="text-muted-foreground m-0 overflow-x-auto font-mono text-[0.82em] leading-relaxed"
              tabIndex={0}
            >
              {source}
            </pre>
          </>
        )}
      </div>
      {caption ? (
        <figcaption
          className="bg-muted/30 text-muted-foreground border-t px-3 py-2 text-sm"
          data-pretext-diagram-caption=""
          id={captionId}
        >
          {caption}
        </figcaption>
      ) : null}
    </figure>
  );
}

function DiagramCopyButton({
  ariaLabel,
  className,
  text,
}: {
  ariaLabel: string;
  className?: string;
  text: string;
}) {
  const [isCopied, setIsCopied] = React.useState(false);

  return (
    <button
      aria-label={isCopied ? "Copied" : ariaLabel}
      className={[
        "text-muted-foreground hover:bg-background hover:text-foreground focus-visible:ring-ring inline-flex size-7 items-center justify-center rounded-md transition focus-visible:ring-2 focus-visible:outline-none",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      type="button"
      onClick={() => {
        void navigator.clipboard?.writeText(text).then(() => {
          setIsCopied(true);
          window.setTimeout(() => setIsCopied(false), 1200);
        });
      }}
    >
      {isCopied ? (
        <Check aria-hidden="true" className="size-3.5" />
      ) : (
        <Clipboard aria-hidden="true" className="size-3.5" />
      )}
    </button>
  );
}

async function renderMermaidDiagram(
  source: string,
  id: string,
): Promise<DiagramState> {
  const state = await getCachedMermaidDiagram(source);
  return state.status === "ready"
    ? { status: "ready", svg: scopeCachedMermaidSvg(state.svg, id) }
    : state;
}

function getCachedMermaidDiagram(source: string) {
  const key = `${MERMAID_CONFIG.theme}\0${source}`;
  let cached = mermaidDiagramCache.get(key);
  if (!cached) {
    cached = loadMermaidDiagram(source);
    mermaidDiagramCache.set(key, cached);
    while (mermaidDiagramCache.size > 64) {
      const oldestKey = mermaidDiagramCache.keys().next().value;
      if (!oldestKey) break;
      mermaidDiagramCache.delete(oldestKey);
    }
  }
  return cached;
}

async function loadMermaidDiagram(source: string): Promise<DiagramState> {
  try {
    const mermaidModule = await import("mermaid");
    const mermaid = mermaidModule.default;
    mermaid.initialize?.(MERMAID_CONFIG);
    const result = await mermaid.render(
      `markdown-diagram-cache-${hashMermaidSource(source)}`,
      source,
    );
    return { status: "ready", svg: sanitizeSvg(result.svg) };
  } catch (error) {
    const message = error instanceof Error ? error.message : "Invalid diagram";
    if (!/getBBox|layout|force-basic-fallback/i.test(message)) {
      return { status: "failed", message };
    }
    return renderBasicMermaidDiagram(source);
  }
}

function scopeCachedMermaidSvg(svg: string, idPrefix: string) {
  if (typeof DOMParser === "undefined") return svg;
  const document = new DOMParser().parseFromString(svg, "image/svg+xml");
  const root = document.documentElement;
  if (!root || root.tagName.toLowerCase() !== "svg") return svg;

  const ids = new Map<string, string>();
  for (const element of Array.from(root.querySelectorAll("[id]"))) {
    const id = element.getAttribute("id");
    if (!id) continue;
    const nextId = `${idPrefix}-${id}`;
    ids.set(id, nextId);
    element.setAttribute("id", nextId);
  }
  if (!ids.size) return new XMLSerializer().serializeToString(root);

  for (const element of Array.from(root.querySelectorAll("*"))) {
    for (const attribute of Array.from(element.attributes)) {
      const value = attribute.value;
      let nextValue = value;
      for (const [oldId, nextId] of ids) {
        nextValue = nextValue
          .replaceAll(`url(#${oldId})`, `url(#${nextId})`)
          .replaceAll(`#${oldId}`, `#${nextId}`);
      }
      if (nextValue !== value) element.setAttribute(attribute.name, nextValue);
    }
  }

  return new XMLSerializer().serializeToString(root);
}

function hashMermaidSource(source: string) {
  let hash = 2166136261;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function renderBasicMermaidDiagram(source: string): ReadyDiagramState {
  const kind = diagramKind(source);
  const lines = readableDiagramLines(source);
  const escaped = escapeHtml(lines.join(" | ") || describeDiagram(source));
  const piePaths =
    kind === "pie"
      ? '<path d="M20 20h20v20H20z"/><path d="M44 20h20v20H44z"/><path d="M68 20h20v20H68z"/>'
      : "";
  return {
    status: "ready",
    svg: `<svg role="img" aria-label="Mermaid diagram" data-pretext-basic-mermaid="${kind}" viewBox="0 0 720 160" width="100%" height="160" xmlns="http://www.w3.org/2000/svg"><rect width="720" height="160" rx="8" fill="currentColor" opacity="0.05"/>${piePaths}<text x="24" y="82" fill="currentColor" font-family="monospace" font-size="16">${escaped}</text></svg>`,
  };
}

function sanitizeSvg(svg: string) {
  if (typeof DOMParser === "undefined") return svg;

  const document = new DOMParser().parseFromString(svg, "image/svg+xml");
  const root = document.documentElement;
  if (!root || root.tagName.toLowerCase() !== "svg") {
    const fallback = renderBasicMermaidDiagram("");
    return fallback.status === "ready" ? fallback.svg : "";
  }

  for (const element of Array.from(root.querySelectorAll("*"))) {
    const tagName = element.tagName.toLowerCase();
    if (
      tagName === "script" ||
      tagName === "a" ||
      tagName === "animate" ||
      tagName === "foreignobject" ||
      tagName === "image" ||
      tagName === "iframe" ||
      tagName === "object" ||
      tagName === "embed" ||
      tagName === "style" ||
      tagName === "use"
    ) {
      element.remove();
      continue;
    }

    for (const attribute of Array.from(element.attributes)) {
      const name = attribute.name.toLowerCase();
      const value = attribute.value.trim();
      if (name.startsWith("on") || name === "style") {
        element.removeAttribute(attribute.name);
        continue;
      }
      if ((name === "id" || name === "name") && isDomClobberingId(value)) {
        element.setAttribute(attribute.name, `user-content-${value}`);
        continue;
      }
      if (
        (name === "href" || name.endsWith(":href") || name === "src") &&
        !isSafeSvgReference(value)
      ) {
        element.removeAttribute(attribute.name);
      }
    }
  }

  for (const attribute of Array.from(root.attributes)) {
    const name = attribute.name.toLowerCase();
    if (name.startsWith("on") || name === "style") {
      root.removeAttribute(attribute.name);
      continue;
    }
    if (
      (name === "id" || name === "name") &&
      isDomClobberingId(attribute.value)
    ) {
      root.setAttribute(attribute.name, `user-content-${attribute.value}`);
    }
  }

  return new XMLSerializer()
    .serializeToString(root)
    .replace(/^<svg\b([^>]*)\brole="([^"]*)"([^>]*)>/, '<svg role="$2"$1$3>');
}

function isSafeSvgReference(value: string) {
  return (
    value === "" ||
    value.startsWith("#") ||
    value.startsWith("data:image/") ||
    /^https?:\/\//i.test(value)
  );
}

function readDiagramLimitMessage(source: string) {
  if (source.length > MERMAID_MAX_SOURCE_LENGTH) {
    return "Mermaid diagram too large to render safely. Copy the source and render it in a dedicated diagram tool.";
  }
  if (source.split(/\r\n|[\n\r\u2028\u2029]/).length > MERMAID_MAX_LINES) {
    return "Mermaid diagram has too many lines to render safely. Copy the source and render it in a dedicated diagram tool.";
  }
  return null;
}

function describeDiagram(source: string) {
  const lines = semanticDiagramLines(source);
  const kind = diagramKind(source);
  if (kind === "graph") {
    const direction = lines[0]
      ?.match(/\b(?:graph|flowchart)\s+([A-Z]{2})\b/i)?.[1]
      ?.toUpperCase();
    const directionText = direction === "LR" ? "left to right" : "top down";
    const edges = lines.filter((line) => /-->|---|-.->|==>/.test(line)).length;
    const nodes = new Set<string>();
    for (const line of lines) {
      for (const match of line.matchAll(/\b([A-Za-z][\w-]*)\b/g)) {
        const value = match[1]!;
        if (
          !["graph", "flowchart", "TD", "LR", "TB", "BT", "RL"].includes(value)
        ) {
          nodes.add(value);
        }
      }
    }
    return `Mermaid graph diagram flowing ${directionText}, with ${nodes.size} nodes and ${edges} edge${edges === 1 ? "" : "s"}.`;
  }
  if (kind === "sequence") {
    const messages = lines.filter((line) =>
      /->>|-->>|->|-->/.test(line),
    ).length;
    const participants = new Set<string>();
    for (const line of lines) {
      const participant = /^participant\s+\S+(?:\s+as\s+(.+))?/i.exec(line);
      if (participant)
        participants.add(participant[1] ?? line.split(/\s+/)[1]!);
      for (const side of line.split(/->>|-->>|->|-->/)) {
        const name = side.split(":")[0]?.trim();
        if (name && !/^sequenceDiagram/i.test(name)) participants.add(name);
      }
    }
    return `Mermaid sequence diagram with ${participants.size} participants and ${messages} message${messages === 1 ? "" : "s"}.`;
  }
  if (kind === "state") {
    const transitions = lines.filter((line) => /-->/.test(line)).length;
    const states = new Set<string>();
    for (const line of lines) {
      const stateAlias = /^state\s+"([^"]+)"\s+as\s+(\w+)/.exec(line);
      if (stateAlias) {
        states.add(stateAlias[1]!);
        continue;
      }
      if (!/-->/.test(line)) continue;
      for (const side of line.split(/-->/)) {
        const name = side
          .split(":")[0]!
          .replace(/\[\*\]/g, "")
          .trim();
        if (name && !/^stateDiagram/.test(name)) {
          states.add(name);
        }
      }
    }
    return `Mermaid state diagram with ${states.size} states and ${transitions} transitions.`;
  }
  if (kind === "class") {
    const relationships = lines.filter((line) =>
      /<\|--|--|<--|\.\./.test(line),
    ).length;
    const classes = new Set<string>();
    for (const line of lines) {
      for (const match of line.matchAll(/\b([A-Z][A-Za-z0-9_]*)\b/g))
        classes.add(match[1]!);
    }
    return `Mermaid class diagram with ${classes.size} classes and ${relationships} relationship${relationships === 1 ? "" : "s"}.`;
  }
  if (kind === "er") {
    const relationships = lines.filter((line) =>
      /\|\||o\{|\|\{/.test(line),
    ).length;
    const entities = new Set<string>();
    for (const line of lines) {
      for (const match of line.matchAll(/\b([A-Z][A-Z0-9_]*)\b/g)) {
        if (!["ERDIAGRAM"].includes(match[1]!)) entities.add(match[1]!);
      }
    }
    return `Mermaid entity relationship diagram with ${entities.size} entities and ${relationships} relationships.`;
  }
  if (kind === "journey")
    return `Mermaid journey diagram with ${countLinesStarting(lines, "section ")} sections and ${lines.filter((line) => /:\s*\d+\s*:/.test(line)).length} tasks.`;
  if (kind === "gantt")
    return `Mermaid Gantt chart with ${countLinesStarting(lines, "section ")} sections and ${lines.filter((line) => /:/.test(line) && !/^dateFormat/i.test(line) && !/^title\b/i.test(line)).length} tasks.`;
  if (kind === "gitGraph")
    return `Mermaid Git graph with ${countLinesStarting(lines, "branch ")} branch, ${countExact(lines, "commit")} commits, and ${countLinesStarting(lines, "merge ")} merge.`;
  if (kind === "timeline")
    return `Mermaid timeline with ${countLinesStarting(lines, "section ")} sections and ${lines.filter((line) => /^\d/.test(line)).length} events.`;
  if (kind === "mindmap")
    return `Mermaid mind map with ${Math.max(0, lines.length - 1)} nodes.`;
  if (kind === "quadrantChart")
    return `Mermaid quadrant chart with ${lines.filter((line) => /:\s*\[[^\]]+\]/.test(line)).length} points.`;
  if (kind === "requirementDiagram")
    return `Mermaid requirement diagram with ${countLinesStarting(lines, "requirement ")} requirement, ${countLinesStarting(lines, "element ")} element, and ${lines.filter((line) => /-\s*\w+\s*->/.test(line)).length} relationship.`;
  if (kind === "xychart") {
    const series = lines.filter((line) => /^(bar|line)\s+\[/.test(line));
    const values = series.reduce(
      (sum, line) => sum + (line.match(/-?\d+(?:\.\d+)?/g)?.length ?? 0),
      0,
    );
    return `Mermaid XY chart with ${series.length} series and ${values} values.`;
  }
  if (kind === "sankey") {
    const flows = lines.filter((line) => line.includes(","));
    const nodes = new Set(
      flows.flatMap((line) =>
        line
          .split(",")
          .slice(0, 2)
          .map((item) => item.trim()),
      ),
    );
    return `Mermaid Sankey diagram with ${nodes.size} nodes and ${flows.length} flows.`;
  }
  if (kind === "c4")
    return `Mermaid C4 diagram with ${lines.filter((line) => /^(Person|System)\(/.test(line)).length} nodes and ${countLinesStarting(lines, "Rel(")} relationship.`;
  if (kind === "pie") {
    const values = lines
      .flatMap((line) => line.match(/:\s*(\d+(?:\.\d+)?)/)?.[1] ?? [])
      .map(Number);
    const total = values.reduce((sum, value) => sum + value, 0);
    return `Mermaid pie chart with ${values.length} slices and total value ${total}.`;
  }
  return "Mermaid diagram";
}

function estimateDiagramBodyHeight(source: string) {
  switch (diagramKind(source)) {
    case "graph":
      return 286;
    case "sequence":
      return 160;
    case "state":
      return 238;
    case "class":
      return 220;
    case "er":
      return 292;
    case "journey":
      return 270;
    case "gantt":
      return 300;
    case "gitGraph":
      return 212;
    case "timeline":
      return 270;
    case "mindmap":
      return 232;
    case "quadrantChart":
      return 296;
    case "requirementDiagram":
      return 230;
    case "xychart":
      return 334;
    case "sankey":
      return 310;
    case "c4":
      return 236;
    case "pie":
      return 224;
    default:
      return 180;
  }
}

function diagramKind(source: string) {
  const first = semanticDiagramLines(source)[0] ?? "";
  if (/^(?:graph|flowchart)\b/i.test(first)) return "graph";
  if (/^sequenceDiagram\b/i.test(first)) return "sequence";
  if (/^stateDiagram/i.test(first)) return "state";
  if (/^classDiagram\b/i.test(first)) return "class";
  if (/^erDiagram\b/i.test(first)) return "er";
  if (/^journey\b/i.test(first)) return "journey";
  if (/^gantt\b/i.test(first)) return "gantt";
  if (/^gitGraph\b/i.test(first)) return "gitGraph";
  if (/^timeline\b/i.test(first)) return "timeline";
  if (/^mindmap\b/i.test(first)) return "mindmap";
  if (/^quadrantChart\b/i.test(first)) return "quadrantChart";
  if (/^requirementDiagram\b/i.test(first)) return "requirementDiagram";
  if (/^xychart/i.test(first)) return "xychart";
  if (/^sankey/i.test(first)) return "sankey";
  if (/^C4/i.test(first)) return "c4";
  if (/^pie\b/i.test(first)) return "pie";
  return "source";
}

function semanticDiagramLines(source: string) {
  return stripMermaidFrontmatter(source)
    .split(/\r\n|[\n\r\u2028\u2029]/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("%%"));
}

function readableDiagramLines(source: string) {
  const lines = semanticDiagramLines(source);
  if (diagramKind(source) === "pie") {
    return lines.map((line) => {
      const match = /"([^"]+)"\s*:\s*(\d+(?:\.\d+)?)/.exec(line);
      return match ? `${match[1]} ${match[2]} (${match[2]}%)` : line;
    });
  }
  return lines;
}

function stripMermaidFrontmatter(source: string) {
  const lines = source.split(/\r\n|[\n\r\u2028\u2029]/);
  if (lines[0]?.trim() !== "---") return source;
  const end = lines.findIndex(
    (line, index) => index > 0 && line.trim() === "---",
  );
  return end === -1 ? source : lines.slice(end + 1).join("\n");
}

function countLinesStarting(lines: readonly string[], prefix: string) {
  return lines.filter((line) => line.startsWith(prefix)).length;
}

function countExact(lines: readonly string[], value: string) {
  return lines.filter((line) => line === value).length;
}

function isDomClobberingId(id: string) {
  return ["constructor", "forms", "images", "location", "__proto__"].includes(
    id,
  );
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

"use client";

import type {
  MarkdownHastElement,
  MarkdownHastNode,
} from "./markdown-hast-types";
import {
  markdownSourceRangeFromPosition,
  markdownSourceTextForRange,
  type MarkdownSourceRange,
} from "./markdown-source-map";
import {
  createMarkdownUnifiedDocument,
  type MarkdownUnifiedDocument,
} from "./markdown-unified-pipeline";

const TARGET_CHUNK_SOURCE_LINES = 42;
const MAX_CHUNK_SOURCE_LINES = 64;
const HOSTILE_CODE_LINE_COUNT = 400;
const HOSTILE_HAST_NODE_COUNT = 3_000;
const HOSTILE_HAST_DEPTH = 80;
const HOSTILE_TEXT_LENGTH = 20_000;
const HOSTILE_TABLE_CELL_COUNT = 2_000;
const DOCUMENT_CACHE_LIMIT = 24;

const markdownGreenfieldDocumentCache = new Map<
  string,
  {
    document: MarkdownGreenfieldDocument;
    text: string;
  }
>();

export type MarkdownGreenfieldBlockKind =
  | "blockquote"
  | "code"
  | "component"
  | "diagram"
  | "footnotes"
  | "frontmatter"
  | "heading"
  | "html"
  | "image"
  | "list"
  | "math"
  | "paragraph"
  | "table"
  | "thematicBreak"
  | "unknown";

export type MarkdownGreenfieldDocument = {
  blocks: MarkdownGreenfieldBlock[];
  chunks: MarkdownGreenfieldChunk[];
  fragmentTargets: MarkdownGreenfieldFragmentTarget[];
  headings: MarkdownGreenfieldHeading[];
  lineCount: number;
  text: string;
  unified: MarkdownUnifiedDocument;
  wordCount: number;
};

export type MarkdownGreenfieldHeading = {
  blockId: string;
  id: string;
  sourceLine: number;
  text: string;
};

export type MarkdownGreenfieldFragmentTarget = {
  blockId: string;
  id: string;
  sourceLine: number;
};

export type MarkdownGreenfieldBlock = {
  hastChildren: MarkdownHastNode[];
  id: string;
  index: number;
  isGenerated: boolean;
  isHostile: boolean;
  kind: MarkdownGreenfieldBlockKind;
  sourceRange: MarkdownSourceRange | null;
  sourceText: string;
};

export type MarkdownGreenfieldChunk = {
  blockIds: string[];
  hastChildren: MarkdownHastNode[];
  id: string;
  index: number;
  isHostile: boolean;
  sourceEndLine: number;
  sourceRange: MarkdownSourceRange | null;
  sourceStartLine: number;
  sourceText: string;
};

export function createMarkdownGreenfieldDocument(
  markdown: string,
): MarkdownGreenfieldDocument {
  const text = markdown.length ? markdown : " ";
  const cacheKey = markdownGreenfieldDocumentTextKey(text);
  const cached = markdownGreenfieldDocumentCache.get(cacheKey);
  if (cached?.text === text) {
    markdownGreenfieldDocumentCache.delete(cacheKey);
    markdownGreenfieldDocumentCache.set(cacheKey, cached);
    return cached.document;
  }

  const document = createUncachedMarkdownGreenfieldDocument(text);
  markdownGreenfieldDocumentCache.set(cacheKey, {
    document,
    text,
  });
  while (markdownGreenfieldDocumentCache.size > DOCUMENT_CACHE_LIMIT) {
    const oldestKey = markdownGreenfieldDocumentCache.keys().next().value;
    if (!oldestKey) break;
    markdownGreenfieldDocumentCache.delete(oldestKey);
  }

  return document;
}

function createUncachedMarkdownGreenfieldDocument(
  text: string,
): MarkdownGreenfieldDocument {
  const unified = createMarkdownUnifiedDocument(text);
  normalizeMarkdownGreenfieldHeadingIds(unified.hast.children, unified);
  normalizeMarkdownGreenfieldTables(unified.hast.children);
  annotateMarkdownGreenfieldSourceMetadata(unified.hast.children, unified);
  const blocks = createMarkdownGreenfieldBlocks({ text, unified });
  const chunks = createMarkdownGreenfieldChunks({ blocks, text });
  const headings = createMarkdownGreenfieldHeadings(blocks);
  const fragmentTargets = createMarkdownGreenfieldFragmentTargets({
    blocks,
    unified,
  });
  freezeMarkdownHastNode(unified.hast);

  return freezeMarkdownGreenfieldDocument({
    blocks,
    chunks,
    fragmentTargets,
    headings,
    lineCount: unified.sourceMap.lineCount,
    text,
    unified,
    wordCount: text.trim().split(/\s+/).filter(Boolean).length,
  });
}

export function findMarkdownGreenfieldHeadingById(
  document: MarkdownGreenfieldDocument,
  headingId: string,
) {
  const normalizedId = headingId.replace(/^#/, "");
  return document.headings.find((heading) => heading.id === normalizedId);
}

export function findMarkdownGreenfieldFragmentTargetById(
  document: MarkdownGreenfieldDocument,
  fragmentId: string,
) {
  const normalizedId = normalizeFragmentTargetId(fragmentId);
  return document.fragmentTargets.find((target) => target.id === normalizedId);
}

export function findMarkdownGreenfieldBlockById(
  document: MarkdownGreenfieldDocument,
  blockId: string,
) {
  return document.blocks.find((block) => block.id === blockId) ?? null;
}

export function findMarkdownGreenfieldChunkByBlockId(
  document: MarkdownGreenfieldDocument,
  blockId: string,
) {
  return (
    document.chunks.find((chunk) => chunk.blockIds.includes(blockId)) ?? null
  );
}

export function findMarkdownGreenfieldBlockBySourceLine(
  document: MarkdownGreenfieldDocument,
  sourceLine: number,
) {
  const line = clampSourceLine(sourceLine, document.lineCount);
  return (
    document.blocks.find((block) => {
      const range = block.sourceRange;
      return range && range.startLine <= line && range.endLine >= line;
    }) ?? null
  );
}

export function findMarkdownGreenfieldChunkBySourceLine(
  document: MarkdownGreenfieldDocument,
  sourceLine: number,
) {
  const block = findMarkdownGreenfieldBlockBySourceLine(document, sourceLine);
  if (block) return findMarkdownGreenfieldChunkByBlockId(document, block.id);

  const line = clampSourceLine(sourceLine, document.lineCount);
  return (
    document.chunks.find(
      (chunk) => chunk.sourceStartLine <= line && chunk.sourceEndLine >= line,
    ) ?? null
  );
}

export function findMarkdownGreenfieldBlockBySourceOffset(
  document: MarkdownGreenfieldDocument,
  sourceOffset: number,
) {
  const offset = clampSourceOffset(sourceOffset, document.text.length);
  return (
    document.blocks.find((block) => {
      const range = block.sourceRange;
      return range && range.startOffset <= offset && range.endOffset > offset;
    }) ?? null
  );
}

export function findMarkdownGreenfieldChunkBySourceOffset(
  document: MarkdownGreenfieldDocument,
  sourceOffset: number,
) {
  const block = findMarkdownGreenfieldBlockBySourceOffset(
    document,
    sourceOffset,
  );
  return block
    ? findMarkdownGreenfieldChunkByBlockId(document, block.id)
    : null;
}

function createMarkdownGreenfieldBlocks({
  text,
  unified,
}: {
  text: string;
  unified: MarkdownUnifiedDocument;
}) {
  const blocks: MarkdownGreenfieldBlock[] = [];

  for (const child of unified.hast.children) {
    if (isWhitespaceText(child)) continue;

    const directSourceRange = markdownSourceRangeFromPosition({
      position: child.position,
      sourceMap: unified.sourceMap,
    });
    const sourceRange =
      directSourceRange ?? markdownSyntheticSourceRangeForNode(child, unified);
    const kind = markdownBlockKindForHastChild(child);
    const sourceText = markdownSourceTextForRange({
      range: sourceRange,
      sourceMap: unified.sourceMap,
    });
    const line = sourceRange?.startLine ?? unified.sourceMap.lineCount;
    const block: MarkdownGreenfieldBlock = {
      hastChildren: [child],
      id: `block-${blocks.length + 1}-${line}-${kind}`,
      index: blocks.length,
      isGenerated: !directSourceRange,
      isHostile: isHostileMarkdownGreenfieldBlock({
        child,
        kind,
        sourceText,
      }),
      kind,
      sourceRange,
      sourceText:
        sourceText ||
        (sourceRange
          ? text.slice(sourceRange.startOffset, sourceRange.endOffset)
          : ""),
    };
    blocks.push(block);
  }

  if (!blocks.length) {
    blocks.push({
      hastChildren: [],
      id: "block-1-empty",
      index: 0,
      isGenerated: true,
      isHostile: false,
      kind: "paragraph",
      sourceRange: {
        endLine: 1,
        endOffset: text.length,
        startLine: 1,
        startOffset: 0,
      },
      sourceText: text,
    });
  }

  return blocks;
}

function createMarkdownGreenfieldChunks({
  blocks,
  text,
}: {
  blocks: readonly MarkdownGreenfieldBlock[];
  text: string;
}) {
  const chunks: MarkdownGreenfieldChunk[] = [];
  let current: MarkdownGreenfieldBlock[] = [];

  const flush = () => {
    if (!current.length) return;
    chunks.push(createChunk(current, chunks.length, text));
    current = [];
  };

  for (const block of blocks) {
    if (block.isHostile) {
      flush();
      current.push(block);
      flush();
      continue;
    }

    const nextLineCount = lineCountForBlocks([...current, block]);
    const startsNewChunk =
      current.length > 0 &&
      block.kind === "heading" &&
      nextLineCount >= TARGET_CHUNK_SOURCE_LINES;
    const exceedsMax =
      current.length > 0 && nextLineCount > MAX_CHUNK_SOURCE_LINES;

    if (startsNewChunk || exceedsMax) flush();
    current.push(block);
  }

  flush();
  return chunks;
}

function createChunk(
  blocks: readonly MarkdownGreenfieldBlock[],
  index: number,
  text: string,
): MarkdownGreenfieldChunk {
  const ranges = blocks
    .map((block) => block.sourceRange)
    .filter((range): range is MarkdownSourceRange => Boolean(range));
  const sourceRange = ranges.length
    ? {
        endLine: Math.max(...ranges.map((range) => range.endLine)),
        endOffset: Math.max(...ranges.map((range) => range.endOffset)),
        startLine: Math.min(...ranges.map((range) => range.startLine)),
        startOffset: Math.min(...ranges.map((range) => range.startOffset)),
      }
    : null;
  const sourceStartLine =
    sourceRange?.startLine ?? blocks[0]?.sourceRange?.startLine ?? 1;
  const sourceEndLine =
    sourceRange?.endLine ??
    blocks[blocks.length - 1]?.sourceRange?.endLine ??
    sourceStartLine;

  return {
    blockIds: blocks.map((block) => block.id),
    hastChildren: blocks.flatMap((block) => block.hastChildren),
    id: `chunk-${index + 1}-${sourceStartLine}`,
    index,
    isHostile: blocks.some((block) => block.isHostile),
    sourceEndLine,
    sourceRange,
    sourceStartLine,
    sourceText: sourceRange
      ? text.slice(sourceRange.startOffset, sourceRange.endOffset)
      : "",
  };
}

function createMarkdownGreenfieldHeadings(
  blocks: readonly MarkdownGreenfieldBlock[],
) {
  return blocks.flatMap((block) => {
    const element = readHastElement(block.hastChildren[0]);
    if (!element || !/^h[1-6]$/.test(element.tagName)) return [];

    const id = readStringProperty(element.properties?.id);
    if (!id) return [];

    return [
      {
        blockId: block.id,
        id,
        sourceLine: block.sourceRange?.startLine ?? 1,
        text: extractHastText(element).trim(),
      },
    ];
  });
}

function createMarkdownGreenfieldFragmentTargets({
  blocks,
  unified,
}: {
  blocks: readonly MarkdownGreenfieldBlock[];
  unified: MarkdownUnifiedDocument;
}) {
  const targets = new Map<string, MarkdownGreenfieldFragmentTarget>();

  for (const block of blocks) {
    for (const child of block.hastChildren) {
      collectFragmentTargets({
        block,
        node: child,
        targets,
        unified,
      });
    }
  }

  return Array.from(targets.values());
}

function collectFragmentTargets({
  block,
  node,
  targets,
  unified,
}: {
  block: MarkdownGreenfieldBlock;
  node: MarkdownHastNode;
  targets: Map<string, MarkdownGreenfieldFragmentTarget>;
  unified: MarkdownUnifiedDocument;
}) {
  const element = readHastElement(node);
  if (!element) return;

  const id = readStringProperty(element.properties?.id);
  if (id) {
    const sourceRange =
      markdownSourceRangeFromPosition({
        position: element.position,
        sourceMap: unified.sourceMap,
      }) ?? block.sourceRange;
    const target = {
      blockId: block.id,
      id,
      sourceLine: sourceRange?.startLine ?? unified.sourceMap.lineCount,
    };

    for (const alias of fragmentTargetAliases(id)) {
      if (!targets.has(alias)) {
        targets.set(alias, { ...target, id: alias });
      }
    }
  }

  for (const child of element.children) {
    collectFragmentTargets({ block, node: child, targets, unified });
  }
}

function markdownSyntheticSourceRangeForNode(
  node: MarkdownHastNode,
  unified: MarkdownUnifiedDocument,
): MarkdownSourceRange | null {
  const ranges = collectMarkdownSourceRanges(node, unified);
  if (!ranges.length) return null;
  return {
    endLine: Math.max(...ranges.map((range) => range.endLine)),
    endOffset: Math.max(...ranges.map((range) => range.endOffset)),
    startLine: Math.min(...ranges.map((range) => range.startLine)),
    startOffset: Math.min(...ranges.map((range) => range.startOffset)),
  };
}

function collectMarkdownSourceRanges(
  node: MarkdownHastNode,
  unified: MarkdownUnifiedDocument,
): MarkdownSourceRange[] {
  const range = markdownSourceRangeFromPosition({
    position: node.position,
    sourceMap: unified.sourceMap,
  });
  const element = readHastElement(node);
  return [
    ...(range ? [range] : []),
    ...(element?.children ?? []).flatMap((child) =>
      collectMarkdownSourceRanges(child, unified),
    ),
  ];
}

function normalizeMarkdownGreenfieldHeadingIds(
  nodes: readonly MarkdownHastNode[],
  unified: MarkdownUnifiedDocument,
) {
  const usedIds = new Map<string, number>();
  for (const node of nodes) {
    normalizeHeadingIdsInNode(node, usedIds, unified);
  }
}

function normalizeHeadingIdsInNode(
  node: MarkdownHastNode,
  usedIds: Map<string, number>,
  unified: MarkdownUnifiedDocument,
) {
  const element = readHastElement(node);
  if (!element) return;

  if (/^h[1-6]$/.test(element.tagName)) {
    const visibleText = extractHastText(element);
    const markdownText = markdownHeadingTextFromSource(element, unified);
    const baseId = safeHeadingIdForText(
      markdownText.includes("__proto__") ? markdownText : visibleText,
    );
    const duplicateCount = usedIds.get(baseId) ?? 0;
    usedIds.set(baseId, duplicateCount + 1);
    element.properties = {
      ...element.properties,
      id: duplicateCount === 0 ? baseId : `${baseId}-${duplicateCount}`,
    };
  }

  for (const child of element.children) {
    normalizeHeadingIdsInNode(child, usedIds, unified);
  }
}

function markdownHeadingTextFromSource(
  element: MarkdownHastElement,
  unified: MarkdownUnifiedDocument,
) {
  const range = markdownSourceRangeFromPosition({
    position: element.position,
    sourceMap: unified.sourceMap,
  });
  if (!range) return "";
  return markdownSourceTextForRange({
    range,
    sourceMap: unified.sourceMap,
  })
    .replace(/^\s{0,3}#{1,6}[ \t]*/, "")
    .replace(/[ \t]+#*\s*$/, "")
    .trim();
}

function safeHeadingIdForText(text: string) {
  const slug =
    text
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^\w\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-") || "section";

  return isDomClobberingId(slug) ? `section-${slug}` : slug;
}

function normalizeFragmentTargetId(fragmentId: string) {
  return decodeURIComponent(fragmentId.replace(/^#/, ""));
}

function fragmentTargetAliases(id: string) {
  const aliases = new Set<string>([normalizeFragmentTargetId(id)]);
  const withoutRepeatedClobberPrefix = id.replace(
    /^(user-content-)+/,
    "user-content-",
  );
  aliases.add(withoutRepeatedClobberPrefix);
  aliases.add(withoutRepeatedClobberPrefix.replace(/^user-content-/, ""));
  return Array.from(aliases).filter(Boolean);
}

function normalizeMarkdownGreenfieldTables(nodes: readonly MarkdownHastNode[]) {
  let tableIndex = 0;
  for (const node of nodes) {
    tableIndex = normalizeTablesInNode(node, tableIndex);
  }
}

function normalizeTablesInNode(node: MarkdownHastNode, tableIndex: number) {
  const element = readHastElement(node);
  if (!element) return tableIndex;

  if (element.tagName === "table") {
    normalizeTableElement(element, tableIndex);
    tableIndex += 1;
  }

  for (const child of element.children) {
    tableIndex = normalizeTablesInNode(child, tableIndex);
  }
  return tableIndex;
}

function normalizeTableElement(table: MarkdownHastElement, tableIndex: number) {
  const rows = tableRows(table);
  const headerIds = new Map<number, string>();

  rows.forEach((row, rowIndex) => {
    row.properties = {
      ...row.properties,
      ariaRowIndex: rowIndex + 1,
      dataPretextTableRowIndex: rowIndex + 1,
    };

    tableCells(row).forEach((cell, columnIndex) => {
      const column = columnIndex + 1;
      const properties = {
        ...cell.properties,
        ariaColIndex: column,
        dataPretextTableColumnIndex: column,
      };
      if (cell.tagName === "th") {
        const id = `markdown-table-${tableIndex + 1}-column-${column}`;
        headerIds.set(columnIndex, id);
        cell.properties = {
          ...properties,
          id,
          scope: "col",
        };
      } else {
        cell.properties = {
          ...properties,
          headers: headerIds.get(columnIndex),
        };
      }
    });
  });
}

function annotateMarkdownGreenfieldSourceMetadata(
  nodes: readonly MarkdownHastNode[],
  unified: MarkdownUnifiedDocument,
) {
  for (const node of nodes) {
    annotateSourceMetadataInNode(node, unified);
  }
}

function annotateSourceMetadataInNode(
  node: MarkdownHastNode,
  unified: MarkdownUnifiedDocument,
) {
  const element = readHastElement(node);
  if (!element) return;

  const sourceRange = markdownSourceRangeFromPosition({
    position: element.position,
    sourceMap: unified.sourceMap,
  });
  if (sourceRange) {
    element.properties = {
      ...element.properties,
      dataPretextSourceEndLine: sourceRange.endLine,
      dataPretextSourceEndOffset: sourceRange.endOffset,
      dataPretextSourceStartLine: sourceRange.startLine,
      dataPretextSourceStartOffset: sourceRange.startOffset,
    };
  }

  for (const child of element.children) {
    annotateSourceMetadataInNode(child, unified);
  }
}

function tableRows(element: MarkdownHastElement) {
  const rows: MarkdownHastElement[] = [];
  for (const child of element.children) {
    const childElement = readHastElement(child);
    if (!childElement) continue;
    if (childElement.tagName === "tr") {
      rows.push(childElement);
    } else if (
      childElement.tagName === "thead" ||
      childElement.tagName === "tbody" ||
      childElement.tagName === "tfoot"
    ) {
      rows.push(...tableRows(childElement));
    }
  }
  return rows;
}

function tableCells(row: MarkdownHastElement) {
  return row.children
    .map(readHastElement)
    .filter(
      (child): child is MarkdownHastElement =>
        child?.tagName === "td" || child?.tagName === "th",
    );
}

function isDomClobberingId(id: string) {
  return [
    "__proto__",
    "constructor",
    "document",
    "forms",
    "history",
    "location",
    "name",
    "prototype",
    "window",
  ].includes(id);
}

function markdownBlockKindForHastChild(
  child: MarkdownHastNode,
): MarkdownGreenfieldBlockKind {
  const element = readHastElement(child);
  if (!element) return child.type === "text" ? "paragraph" : "unknown";

  if (element.properties?.dataFootnotes != null) return "footnotes";
  if (element.properties?.dataMarkdownFrontmatter != null) return "frontmatter";
  if (/^h[1-6]$/.test(element.tagName)) return "heading";
  if (isMarkdownDiagramElement(element)) return "diagram";
  if (isMarkdownComponentElement(element)) return "component";
  if (isDisplayMathElement(element)) return "math";

  switch (element.tagName) {
    case "blockquote":
      return "blockquote";
    case "hr":
      return "thematicBreak";
    case "ol":
    case "ul":
      return "list";
    case "p":
      if (isDisplayMathElement(element)) return "math";
      return firstElementChild(element)?.tagName === "img"
        ? "image"
        : "paragraph";
    case "pre":
      if (isMermaidCodeElement(element)) return "diagram";
      return "code";
    case "table":
      return "table";
    default:
      return "html";
  }
}

function isMarkdownDiagramElement(element: MarkdownHastElement) {
  return (
    readStringProperty(element.properties?.dataPretextComponentName) ===
    "Diagram"
  );
}

function isMarkdownComponentElement(element: MarkdownHastElement) {
  return (
    element.properties?.dataPretextComponentName != null ||
    element.properties?.dataPretextComponentFallback != null ||
    element.properties?.dataPretextCalloutKind != null
  );
}

function isDisplayMathElement(element: MarkdownHastElement): boolean {
  if (
    hasClassName(element, "katex-display") ||
    hasClassName(element, "math-display")
  )
    return true;
  return element.children
    .map(readHastElement)
    .some((child) => child != null && isDisplayMathElement(child));
}

function isMermaidCodeElement(element: MarkdownHastElement) {
  const code = firstElementChild(element);
  return (
    code?.tagName === "code" &&
    ["language-mermaid", "language-mmd", "language-mermaid-js"].some(
      (className) => hasClassName(code, className),
    )
  );
}

function hasClassName(element: MarkdownHastElement, className: string) {
  const classes = element.properties?.className;
  return Array.isArray(classes)
    ? classes.includes(className)
    : typeof classes === "string" && classes.split(/\s+/).includes(className);
}

function isHostileMarkdownGreenfieldBlock({
  child,
  kind,
  sourceText,
}: {
  child: MarkdownHastNode;
  kind: MarkdownGreenfieldBlockKind;
  sourceText: string;
}) {
  if (sourceText.length > HOSTILE_TEXT_LENGTH) return true;
  if (countHastNodes(child) > HOSTILE_HAST_NODE_COUNT) return true;
  if (maxHastDepth(child) > HOSTILE_HAST_DEPTH) return true;
  if (
    kind === "code" &&
    sourceText.split(/\r\n|[\n\r\u2028\u2029]/).length > HOSTILE_CODE_LINE_COUNT
  ) {
    return true;
  }
  if (kind === "table" && countTableCells(child) > HOSTILE_TABLE_CELL_COUNT) {
    return true;
  }
  return false;
}

function countHastNodes(node: MarkdownHastNode): number {
  const element = readHastElement(node);
  return (
    1 +
    (element?.children ?? []).reduce(
      (sum, child) => sum + countHastNodes(child),
      0,
    )
  );
}

function maxHastDepth(node: MarkdownHastNode): number {
  const element = readHastElement(node);
  if (!element?.children.length) return 1;
  return 1 + Math.max(...element.children.map(maxHastDepth));
}

function lineCountForBlocks(blocks: readonly MarkdownGreenfieldBlock[]) {
  const ranges = blocks
    .map((block) => block.sourceRange)
    .filter((range): range is MarkdownSourceRange => Boolean(range));
  if (!ranges.length) return blocks.length;

  return (
    Math.max(...ranges.map((range) => range.endLine)) -
    Math.min(...ranges.map((range) => range.startLine)) +
    1
  );
}

function countTableCells(node: MarkdownHastNode): number {
  const element = readHastElement(node);
  if (!element) return 0;
  const self = element.tagName === "td" || element.tagName === "th" ? 1 : 0;
  return (
    self +
    (element.children ?? []).reduce(
      (sum, child) => sum + countTableCells(child),
      0,
    )
  );
}

function readHastElement(node: unknown): MarkdownHastElement | null {
  return node &&
    typeof node === "object" &&
    (node as MarkdownHastElement).type === "element"
    ? (node as MarkdownHastElement)
    : null;
}

function firstElementChild(element: MarkdownHastElement) {
  return element.children.map(readHastElement).find(Boolean) ?? null;
}

function isWhitespaceText(node: MarkdownHastNode) {
  return (
    node.type === "text" &&
    typeof node.value === "string" &&
    node.value.trim() === ""
  );
}

function readStringProperty(value: unknown) {
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return value.filter(Boolean).join(" ");
  return "";
}

function extractHastText(node: MarkdownHastNode): string {
  if (node.type === "text" && typeof node.value === "string") return node.value;
  const element = readHastElement(node);
  if (!element) return "";
  return element.children.map(extractHastText).join("");
}

function freezeMarkdownHastNode(node: unknown) {
  if (!node || typeof node !== "object" || Object.isFrozen(node)) return;

  const record = node as Record<string, unknown>;
  for (const value of Object.values(record)) {
    if (Array.isArray(value)) {
      value.forEach(freezeMarkdownHastNode);
      Object.freeze(value);
      continue;
    }
    if (value && typeof value === "object") {
      freezeMarkdownHastNode(value);
    }
  }
  Object.freeze(node);
}

function freezeMarkdownGreenfieldDocument(
  document: MarkdownGreenfieldDocument,
) {
  for (const block of document.blocks) {
    if (block.sourceRange) Object.freeze(block.sourceRange);
    Object.freeze(block.hastChildren);
    Object.freeze(block);
  }
  for (const chunk of document.chunks) {
    if (chunk.sourceRange) Object.freeze(chunk.sourceRange);
    Object.freeze(chunk.blockIds);
    Object.freeze(chunk.hastChildren);
    Object.freeze(chunk);
  }
  for (const heading of document.headings) Object.freeze(heading);
  for (const target of document.fragmentTargets) Object.freeze(target);
  Object.freeze(document.blocks);
  Object.freeze(document.chunks);
  Object.freeze(document.headings);
  Object.freeze(document.fragmentTargets);
  return Object.freeze(document);
}

export function markdownGreenfieldDocumentTextKey(text: string) {
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${text.length}:${(hash >>> 0).toString(36)}`;
}

function clampSourceLine(line: number, lineCount: number) {
  if (!Number.isFinite(line)) return 1;
  return Math.max(1, Math.min(lineCount, Math.floor(line)));
}

function clampSourceOffset(offset: number, textLength: number) {
  if (!Number.isFinite(offset)) return 0;
  return Math.max(0, Math.min(textLength, Math.floor(offset)));
}

"use client";

import * as React from "react";

import {
  createMarkdownGreenfieldDocument,
  markdownGreenfieldDocumentTextKey,
  type MarkdownGreenfieldDocument,
} from "./markdown-greenfield-document";

export const MARKDOWN_GREENFIELD_ASYNC_DOCUMENT_MIN_CHARS = 60_000;
const MARKDOWN_GREENFIELD_DOCUMENT_WORKER_ENABLED = false;
const MARKDOWN_GREENFIELD_DOCUMENT_WORKER_READY_TIMEOUT_MS = 800;

type MarkdownIdleWindow = Window &
  typeof globalThis & {
    requestIdleCallback?: Window["requestIdleCallback"];
  };

type MarkdownDocumentState =
  | { status: "failed"; error: Error }
  | { status: "pending" }
  | { status: "ready"; document: MarkdownGreenfieldDocument };

type MarkdownDocumentEntry = {
  key: string;
  listeners: Set<() => void>;
  started: boolean;
  state: MarkdownDocumentState;
  text: string;
};

type MarkdownDocumentWorkerRequest = {
  id: number;
  text: string;
};

type MarkdownDocumentWorkerResponse =
  | {
      type: "ready";
    }
  | {
      document: MarkdownGreenfieldDocument;
      id: number;
      ok: true;
      type: "result";
    }
  | {
      id: number;
      message: string;
      ok: false;
      type: "result";
    };

const markdownDocumentEntries = new Map<string, MarkdownDocumentEntry>();
let nextMarkdownDocumentWorkerRequestId = 1;

export function useMarkdownGreenfieldDocument(text: string) {
  const shouldLoadAsync =
    text.length >= MARKDOWN_GREENFIELD_ASYNC_DOCUMENT_MIN_CHARS;
  const syncDocument = React.useMemo(
    () => (shouldLoadAsync ? null : createMarkdownGreenfieldDocument(text)),
    [shouldLoadAsync, text],
  );
  const entry = React.useMemo(
    () => (shouldLoadAsync ? getMarkdownDocumentEntry(text) : null),
    [shouldLoadAsync, text],
  );
  const asyncState = React.useSyncExternalStore(
    React.useCallback(
      (onStoreChange) => {
        if (!entry) return () => {};
        entry.listeners.add(onStoreChange);
        startMarkdownDocumentEntry(entry);
        return () => {
          entry.listeners.delete(onStoreChange);
        };
      },
      [entry],
    ),
    React.useCallback(() => entry?.state ?? null, [entry]),
    () => null,
  );

  if (syncDocument) return syncDocument;
  if (!asyncState || asyncState.status === "pending") return null;
  if (asyncState.status === "failed") throw asyncState.error;
  return asyncState.document;
}

function getMarkdownDocumentEntry(text: string) {
  const key = markdownGreenfieldDocumentTextKey(text);
  const existing = markdownDocumentEntries.get(key);
  if (existing?.text === text) return existing;

  const entry: MarkdownDocumentEntry = {
    key,
    listeners: new Set(),
    started: false,
    state: { status: "pending" },
    text,
  };
  markdownDocumentEntries.set(key, entry);
  while (markdownDocumentEntries.size > 16) {
    const oldestKey = markdownDocumentEntries.keys().next().value;
    if (!oldestKey || oldestKey === key) break;
    markdownDocumentEntries.delete(oldestKey);
  }
  return entry;
}

function startMarkdownDocumentEntry(entry: MarkdownDocumentEntry) {
  if (entry.started || entry.state.status !== "pending") return;
  entry.started = true;

  if (
    MARKDOWN_GREENFIELD_DOCUMENT_WORKER_ENABLED &&
    typeof Worker !== "undefined"
  ) {
    try {
      startMarkdownDocumentWorker(entry);
      return;
    } catch {
      startMarkdownDocumentFallback(entry);
      return;
    }
  }

  startMarkdownDocumentFallback(entry);
}

function startMarkdownDocumentWorker(entry: MarkdownDocumentEntry) {
  const worker = new Worker(
    new URL("./markdown-greenfield-document.worker", import.meta.url),
    { type: "module" },
  );
  const id = nextMarkdownDocumentWorkerRequestId++;
  let isSettled = false;
  const readyTimeoutId = window.setTimeout(() => {
    fallBackToMainThread();
  }, MARKDOWN_GREENFIELD_DOCUMENT_WORKER_READY_TIMEOUT_MS);

  const fallBackToMainThread = () => {
    if (isSettled) return;
    isSettled = true;
    window.clearTimeout(readyTimeoutId);
    worker.terminate();
    startMarkdownDocumentFallback(entry);
  };

  worker.onmessage = (event: MessageEvent<MarkdownDocumentWorkerResponse>) => {
    if (event.data.type === "ready") {
      window.clearTimeout(readyTimeoutId);
      worker.postMessage({
        id,
        text: entry.text,
      } satisfies MarkdownDocumentWorkerRequest);
      return;
    }
    if (event.data.id !== id || isSettled) return;
    isSettled = true;
    window.clearTimeout(readyTimeoutId);
    worker.terminate();
    if (event.data.ok) {
      publishMarkdownDocumentState(entry, {
        document: event.data.document,
        status: "ready",
      });
      return;
    }
    publishMarkdownDocumentState(entry, {
      error: new Error(event.data.message),
      status: "failed",
    });
  };
  worker.onerror = fallBackToMainThread;
  worker.onmessageerror = fallBackToMainThread;
}

function startMarkdownDocumentFallback(entry: MarkdownDocumentEntry) {
  scheduleMarkdownDocumentTask(() => {
    try {
      publishMarkdownDocumentState(entry, {
        document: createMarkdownGreenfieldDocument(entry.text),
        status: "ready",
      });
    } catch (error) {
      publishMarkdownDocumentState(entry, {
        error:
          error instanceof Error
            ? error
            : new Error("Could not parse Markdown."),
        status: "failed",
      });
    }
  });
}

function scheduleMarkdownDocumentTask(callback: () => void) {
  if (typeof window === "undefined") return;
  const browserWindow = window as MarkdownIdleWindow;
  if (browserWindow.requestIdleCallback) {
    browserWindow.requestIdleCallback(callback, { timeout: 120 });
    return;
  }
  browserWindow.setTimeout(callback, 0);
}

function publishMarkdownDocumentState(
  entry: MarkdownDocumentEntry,
  state: MarkdownDocumentState,
) {
  entry.state = state;
  for (const listener of entry.listeners) listener();
}

import { createMarkdownGreenfieldDocument } from "./markdown-greenfield-document";

type MarkdownDocumentWorkerRequest = {
  id: number;
  text: string;
};

type MarkdownDocumentWorkerResponse =
  | {
      type: "ready";
    }
  | {
      document: ReturnType<typeof createMarkdownGreenfieldDocument>;
      id: number;
      ok: true;
      type: "result";
    }
  | {
      id: number;
      message: string;
      ok: false;
      type: "result";
    };

self.postMessage({ type: "ready" } satisfies MarkdownDocumentWorkerResponse);

self.onmessage = (event: MessageEvent<MarkdownDocumentWorkerRequest>) => {
  const { id, text } = event.data;
  try {
    const document = createMarkdownGreenfieldDocument(text);
    self.postMessage({
      document,
      id,
      ok: true,
      type: "result",
    } satisfies MarkdownDocumentWorkerResponse);
  } catch (error) {
    self.postMessage({
      id,
      message:
        error instanceof Error ? error.message : "Could not parse Markdown.",
      ok: false,
      type: "result",
    } satisfies MarkdownDocumentWorkerResponse);
  }
};

"use client";

import type {
  MarkdownGreenfieldBlock,
  MarkdownGreenfieldChunk,
  MarkdownGreenfieldDocument,
} from "./markdown-greenfield-document";

const DOCUMENT_PADDING_Y = 32;
const CHUNK_PADDING_X = 32;
const MIN_CHUNK_HEIGHT = 64;
// Tuned to the rendered typography (15.5px body at leading-relaxed ≈ 25px,
// 14px mono code at leading-5 = 20px) so estimates track measured heights and
// scroll correction stays minimal.
const BODY_LINE_HEIGHT = 25;
const MONO_LINE_HEIGHT = 20;
const APPROX_BODY_CHAR_WIDTH = 7.9;
const APPROX_MONO_CHAR_WIDTH = 7.8;
export const MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION =
  "greenfield-layout-rich-blocks-v3";
const LAYOUT_CACHE_LIMIT = 64;

const markdownGreenfieldLayoutDocumentIds = new WeakMap<
  MarkdownGreenfieldDocument,
  number
>();
const markdownGreenfieldLayoutCache = new Map<
  string,
  {
    document: MarkdownGreenfieldDocument;
    frame: MarkdownGreenfieldFrame;
  }
>();
let nextMarkdownGreenfieldLayoutDocumentId = 1;

export type MarkdownGreenfieldFrame = {
  chunks: MarkdownGreenfieldChunkFrame[];
  totalHeight: number;
  width: number;
};

export type MarkdownGreenfieldChunkFrame = {
  bottom: number;
  height: number;
  id: string;
  index: number;
  measuredHeight: number | null;
  sourceEndLine: number;
  sourceStartLine: number;
  top: number;
};

export type MarkdownGreenfieldMeasuredHeights = {
  cacheKey?: string;
  get(
    chunk: MarkdownGreenfieldChunk,
    context: MarkdownGreenfieldMeasurementContext,
  ): number | undefined;
};

export type MarkdownGreenfieldMeasurementContext = {
  fontScale: number;
  policyVersion: string;
  width: number;
};

export function layoutMarkdownGreenfieldDocument({
  contentWidth,
  document,
  fontScale,
  measuredHeights,
}: {
  contentWidth: number;
  document: MarkdownGreenfieldDocument;
  fontScale: number;
  measuredHeights?: MarkdownGreenfieldMeasuredHeights;
}): MarkdownGreenfieldFrame {
  const width = Math.max(1, contentWidth);
  const context = {
    fontScale,
    policyVersion: MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
    width,
  };
  const measuredHeightByChunkId = readMarkdownGreenfieldMeasuredHeights({
    context,
    document,
    measuredHeights,
  });
  const cacheKey = markdownGreenfieldLayoutCacheKey({
    context,
    document,
    measuredHeightByChunkId,
    measuredHeightsCacheKey: measuredHeights?.cacheKey,
  });
  const cached = markdownGreenfieldLayoutCache.get(cacheKey);
  if (cached?.document === document) {
    markdownGreenfieldLayoutCache.delete(cacheKey);
    markdownGreenfieldLayoutCache.set(cacheKey, cached);
    return cached.frame;
  }

  const blocksById = new Map(document.blocks.map((block) => [block.id, block]));
  const chunks: MarkdownGreenfieldChunkFrame[] = [];
  let y = DOCUMENT_PADDING_Y;

  for (const chunk of document.chunks) {
    const estimatedHeight = estimateMarkdownGreenfieldChunkHeight({
      blocks: chunk.blockIds
        .map((blockId) => blocksById.get(blockId))
        .filter((block): block is MarkdownGreenfieldBlock => Boolean(block)),
      fontScale,
      width,
    });
    const measuredHeight = measuredHeightByChunkId.get(chunk.id) ?? null;
    const height = Math.max(
      MIN_CHUNK_HEIGHT,
      measuredHeight == null ? estimatedHeight : measuredHeight,
    );
    chunks.push({
      bottom: y + height,
      height,
      id: chunk.id,
      index: chunk.index,
      measuredHeight,
      sourceEndLine: chunk.sourceEndLine,
      sourceStartLine: chunk.sourceStartLine,
      top: y,
    });
    y += height;
  }

  const frame = freezeMarkdownGreenfieldFrame({
    chunks,
    totalHeight: chunks.length ? y + DOCUMENT_PADDING_Y : 0,
    width,
  });
  markdownGreenfieldLayoutCache.set(cacheKey, { document, frame });
  while (markdownGreenfieldLayoutCache.size > LAYOUT_CACHE_LIMIT) {
    const oldestKey = markdownGreenfieldLayoutCache.keys().next().value;
    if (!oldestKey) break;
    markdownGreenfieldLayoutCache.delete(oldestKey);
  }
  return frame;
}

function estimateMarkdownGreenfieldChunkHeight({
  blocks,
  fontScale,
  width,
}: {
  blocks: readonly MarkdownGreenfieldBlock[];
  fontScale: number;
  width: number;
}) {
  const textWidth = Math.max(1, width - CHUNK_PADDING_X * 2);
  const height = blocks.reduce(
    (sum, block) =>
      sum +
      estimateMarkdownGreenfieldBlockHeight({
        block,
        fontScale,
        textWidth,
      }),
    0,
  );
  return Math.max(MIN_CHUNK_HEIGHT, height);
}

function estimateMarkdownGreenfieldBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: MarkdownGreenfieldBlock;
  fontScale: number;
  textWidth: number;
}) {
  if (block.kind === "thematicBreak") return 36 * fontScale;
  if (block.kind === "frontmatter") {
    const lines = Math.max(
      1,
      block.sourceText.split(/\r\n|[\n\r\u2028\u2029]/).length,
    );
    return (72 + lines * MONO_LINE_HEIGHT) * fontScale;
  }
  if (block.kind === "footnotes")
    return estimateTextBlock(block, textWidth, fontScale, 0.9);
  if (block.kind === "heading") {
    return estimateTextBlock(block, textWidth, fontScale, 1.3) + 18 * fontScale;
  }
  if (block.kind === "diagram") return 360 * fontScale;
  if (block.kind === "math") return 120 * fontScale;
  if (block.kind === "component") return 160 * fontScale;
  if (block.kind === "code") {
    const lines = Math.max(
      1,
      block.sourceText.split(/\r\n|[\n\r\u2028\u2029]/).length,
    );
    return 48 * fontScale + lines * MONO_LINE_HEIGHT * fontScale;
  }
  if (block.kind === "table") {
    const rows = Math.max(2, (block.sourceText.match(/\n/g)?.length ?? 1) + 1);
    return (48 + rows * 36) * fontScale;
  }
  if (block.kind === "image") return 280 * fontScale;
  if (block.isHostile) return 420 * fontScale;
  return estimateTextBlock(block, textWidth, fontScale, 1);
}

function estimateTextBlock(
  block: MarkdownGreenfieldBlock,
  textWidth: number,
  fontScale: number,
  multiplier: number,
) {
  const text = block.sourceText || " ";
  const charWidth =
    block.kind === "code" ? APPROX_MONO_CHAR_WIDTH : APPROX_BODY_CHAR_WIDTH;
  const columns = Math.max(12, Math.floor(textWidth / (charWidth * fontScale)));
  const sourceLines = text.split(/\r\n|[\n\r\u2028\u2029]/);
  const visualLines = sourceLines.reduce(
    (sum, line) => sum + Math.max(1, Math.ceil(line.length / columns)),
    0,
  );
  return (
    16 * fontScale + visualLines * BODY_LINE_HEIGHT * fontScale * multiplier
  );
}

function readMarkdownGreenfieldMeasuredHeights({
  context,
  document,
  measuredHeights,
}: {
  context: MarkdownGreenfieldMeasurementContext;
  document: MarkdownGreenfieldDocument;
  measuredHeights?: MarkdownGreenfieldMeasuredHeights;
}) {
  const measuredHeightByChunkId = new Map<string, number>();
  if (!measuredHeights) return measuredHeightByChunkId;

  for (const chunk of document.chunks) {
    const measuredHeight = measuredHeights.get(chunk, context);
    if (
      typeof measuredHeight === "number" &&
      Number.isFinite(measuredHeight) &&
      measuredHeight > 0
    ) {
      measuredHeightByChunkId.set(chunk.id, measuredHeight);
    }
  }
  return measuredHeightByChunkId;
}

function markdownGreenfieldLayoutCacheKey({
  context,
  document,
  measuredHeightByChunkId,
  measuredHeightsCacheKey,
}: {
  context: MarkdownGreenfieldMeasurementContext;
  document: MarkdownGreenfieldDocument;
  measuredHeightByChunkId: ReadonlyMap<string, number>;
  measuredHeightsCacheKey?: string;
}) {
  return [
    markdownGreenfieldLayoutDocumentId(document),
    Math.round(context.width * 100) / 100,
    context.fontScale.toFixed(4),
    context.policyVersion,
    measuredHeightsCacheKey ??
      measuredHeightsDetailedCacheKey(measuredHeightByChunkId),
  ].join(":");
}

function measuredHeightsDetailedCacheKey(
  measuredHeightByChunkId: ReadonlyMap<string, number>,
) {
  return Array.from(measuredHeightByChunkId)
    .map(
      ([chunkId, measuredHeight]) => `${chunkId}:${measuredHeight.toFixed(2)}`,
    )
    .join("|");
}

function markdownGreenfieldLayoutDocumentId(
  document: MarkdownGreenfieldDocument,
) {
  const existing = markdownGreenfieldLayoutDocumentIds.get(document);
  if (existing) return existing;
  const next = nextMarkdownGreenfieldLayoutDocumentId++;
  markdownGreenfieldLayoutDocumentIds.set(document, next);
  return next;
}

function freezeMarkdownGreenfieldFrame(frame: MarkdownGreenfieldFrame) {
  for (const chunk of frame.chunks) Object.freeze(chunk);
  Object.freeze(frame.chunks);
  return Object.freeze(frame);
}

